+func TestEnrichStateReportsContainerStateAndHealth(t *testing.T) {
+	t.Parallel()
+
+	r := newTestRuntimeWithKubeObjects(

+		[]*unstructured.Unstructured{
+			trackerTestNode("r1", nodeRunStateRunning, condition("Ready", "True")),
