package events

import (
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"
	"time"
)

type formatter func(aggregatedEvent) error

func newFormatter(format string, w io.Writer) (formatter, error) {
	normalized := strings.TrimSpace(strings.ToLower(format))
	if normalized == "" {
		normalized = "plain"
	}

	switch normalized {
	case "plain":
		return plainFormatter(w), nil
	case "json":
		return jsonFormatter(w), nil
	default:
		return nil, fmt.Errorf("output format %q is not supported, use 'plain' or 'json'", format)
	}
}

func plainFormatter(w io.Writer) formatter {
	return func(ev aggregatedEvent) error {
		ts := ev.Timestamp
		if ts.IsZero() {
			ts = time.Now()
		}
		ts = ts.UTC()

		actor := ev.ActorID
		if actor == "" {
			actor = ev.ActorName
		}
		if actor == "" {
			actor = "-"
		}

		attrs := mergedEventAttributes(ev)
		keys := make([]string, 0, len(attrs))
		for k := range attrs {
			keys = append(keys, k)
		}
		sort.Strings(keys)

		parts := make([]string, 0, len(keys))
		for _, k := range keys {
			parts = append(parts, fmt.Sprintf("%s=%s", k, attrs[k]))
		}

		suffix := ""
		if len(parts) > 0 {
			suffix = " (" + strings.Join(parts, ", ") + ")"
		}

		_, err := fmt.Fprintf(
			w,
			"%s %s %s %s%s\n",
			ts.Format(time.RFC3339Nano),
			ev.Type,
			ev.Action,
			actor,
			suffix,
		)

		return err
	}
}

func jsonFormatter(w io.Writer) formatter {
	encoder := json.NewEncoder(w)
	encoder.SetEscapeHTML(false)

	return func(ev aggregatedEvent) error {
		copy := ev
		copy.Attributes = mergedEventAttributes(ev)

		return encoder.Encode(copy)
	}
}

func mergedEventAttributes(ev aggregatedEvent) map[string]string {
	if len(ev.Attributes) == 0 && ev.ActorName == "" && ev.ActorFullID == "" {
		return nil
	}

	attrs := make(map[string]string, len(ev.Attributes)+2)
	for k, v := range ev.Attributes {
		if v == "" {
			continue
		}

		attrs[k] = v
	}

	if ev.ActorName != "" {
		attrs["name"] = ev.ActorName
	}

	if ev.ActorFullID != "" {
		attrs["id"] = ev.ActorFullID
	}

	if len(attrs) == 0 {
		return nil
	}

	return attrs
}

package events

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/charmbracelet/log"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clabcore "github.com/srl-labs/containerlab/core"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clabruntime "github.com/srl-labs/containerlab/runtime"
	clabtypes "github.com/srl-labs/containerlab/types"
	clabutils "github.com/srl-labs/containerlab/utils"
)

// Stream subscribes to the selected runtime and netlink sources and forwards
// aggregated events to the configured writer.
func Stream(ctx context.Context, opts Options) error {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	clab, err := clabcore.NewContainerLab(opts.ClabOptions...)
	if err != nil {
		return err
	}

	if clab.LabRuntime != nil {
		return streamLabRuntimeEvents(ctx, clab, opts)
	}

	runtime, ok := clab.Runtimes[opts.Runtime]
	if !ok {
		return fmt.Errorf("runtime %q is not initialized", opts.Runtime)
	}

	printer, err := newFormatter(opts.Format, opts.writer())
	if err != nil {
		return err
	}

	eventCh := make(chan aggregatedEvent, 128)
	registry := newNetlinkRegistry(
		ctx,
		eventCh,
		opts.IncludeInitialState,
		opts.IncludeInterfaceStats,
		opts.StatsInterval,
	)

	containers, err := clab.ListContainers(ctx, clabcore.WithListclabLabelExists())
	if err != nil {
		return fmt.Errorf("failed to list containers: %w", err)
	}

	if opts.IncludeInitialState {
		go emitContainerSnapshots(ctx, containers, eventCh)
	}

	for idx := range containers {
		container := containers[idx]
		if !isRunningContainer(&container) {
			continue
		}

		registry.Start(&container)
	}

	streamOpts := clabruntime.EventStreamOptions{
		Labels: map[string]string{
			clabconstants.Containerlab: "",
		},
	}

	runtimeEvents, runtimeErrs, err := runtime.StreamEvents(ctx, streamOpts)
	if err != nil {
		return fmt.Errorf("failed to stream events for runtime %q: %w", opts.Runtime, err)
	}

	errCh := make(chan error, 1)
	go forwardRuntimeEvents(ctx, runtime, registry, runtimeEvents, runtimeErrs, eventCh, errCh)

	runtimeErrors := errCh

	for {
		select {
		case ev := <-eventCh:
			if err := printer(ev); err != nil {
				log.Debugf("failed to write event: %v", err)
			}
		case err, ok := <-runtimeErrors:
			if !ok {
				runtimeErrors = nil

				continue
			}

			if err != nil && !errors.Is(err, context.Canceled) {
				return err
			}
		case <-ctx.Done():
			return nil
		}
	}
}

func streamLabRuntimeEvents(ctx context.Context, clab *clabcore.CLab, opts Options) error {
	printer, err := newFormatter(opts.Format, opts.writer())
	if err != nil {
		return err
	}

	runtimeEvents, runtimeErrs, err := clab.LabRuntime.StreamEvents(
		ctx,
		labRuntimeEventStreamRequest(clab.Config.Name, clab.LabRuntimeIdentity(), opts),
	)
	if err != nil {
		return fmt.Errorf("failed to stream events for lab runtime %q: %w", opts.Runtime, err)
	}

	for runtimeEvents != nil || runtimeErrs != nil {
		select {
		case ev, ok := <-runtimeEvents:
			if !ok {
				runtimeEvents = nil

				continue
			}

			if err := printer(aggregatedEventFromLabRuntimeEvent(clab, ev)); err != nil {
				log.Debugf("failed to write event: %v", err)
			}
		case err, ok := <-runtimeErrs:
			if !ok {
				runtimeErrs = nil

				continue
			}

			if err != nil && !errors.Is(err, context.Canceled) {
				return err
			}
		case <-ctx.Done():
			return nil
		}
	}

	return nil
}

// labRuntimeEventStreamRequest scopes a lab runtime event stream. A selected lab (--topo or
// --name) limits the stream to that lab in its namespace. Without one the stream covers every
// namespace, unless a namespace override (--namespace, CLAB_KUBE_NAMESPACE) limits it to that
// namespace; the runtime applies the override.
func labRuntimeEventStreamRequest(
	labName string,
	identity clablabruntime.Identity,
	opts Options,
) clablabruntime.EventStreamRequest {
	return clablabruntime.EventStreamRequest{
		Name:                  labName,
		Identity:              identity,
		AllNamespaces:         labName == "",
		IncludeInitialState:   opts.IncludeInitialState,
		IncludeInterfaceStats: opts.IncludeInterfaceStats,
		StatsInterval:         opts.StatsInterval,
	}
}

// aggregatedEventFromLabRuntimeEvent reports a lab runtime event with the attributes the
// container runtimes' events have. A container event describes its node with the container
// record inspect reports for it, the way a Docker event carries the container's labels: as a
// snapshot like the snapshots of local containers, otherwise with the labels, image,
// management addresses and ports a Docker event and its enrichment carry. An interface event
// carries the attributes of the netlink interface events. The runtime's own attributes come on
// top.
func aggregatedEventFromLabRuntimeEvent(
	clab *clabcore.CLab,
	ev clablabruntime.Event,
) aggregatedEvent {
	ts := ev.Timestamp
	if ts.IsZero() {
		ts = time.Now()
	}

	var attributes map[string]string
	switch {
	case ev.Type == clablabruntime.EventTypeContainer && ev.Lab != nil && ev.Node != nil &&
		clab != nil:
		container := clab.LabRuntimeContainer(ev.Lab, *ev.Node)
		if ev.Attributes["origin"] == clablabruntime.EventOriginSnapshot {
			attributes = aggregatedEventFromContainerSnapshot(&container).Attributes
		} else {
			attributes = containerAttributes(&container)
		}
	case ev.Type == clablabruntime.EventTypeInterface && ev.Interface != nil:
		lab := ev.Attributes["lab"]
		if ev.Lab != nil {
			lab = ev.Lab.Name
		}
		attributes = labRuntimeInterfaceAttributes(lab, ev.ActorName, ev.Interface)
	}

	for key, value := range ev.Attributes {
		if attributes == nil {
			attributes = make(map[string]string, len(ev.Attributes))
		}
		attributes[key] = value
	}

	return aggregatedEvent{
		Timestamp:   ts,
		Type:        ev.Type,
		Action:      ev.Action,
		ActorID:     ev.ActorID,
		ActorName:   ev.ActorName,
		ActorFullID: ev.ActorFullID,
		Attributes:  attributes,
	}
}

// containerAttributes are the attributes a container event reports for a container: its labels
// and image, which Docker puts on every container event, and the management addresses and
// ports the events command adds.
func containerAttributes(container *clabruntime.GenericContainer) map[string]string {
	attributes := cloneStringMap(container.Labels)
	if attributes == nil {
		attributes = make(map[string]string)
	}

	if container.Image != "" {
		attributes["image"] = container.Image
	}

	if container.NetworkSettings.IPv4addr != "" {
		attributes["mgmt_ipv4"] = container.GetContainerIPv4()
	}

	if container.NetworkSettings.IPv6addr != "" {
		attributes["mgmt_ipv6"] = container.GetContainerIPv6()
	}

	if ports := exposedPortsAttributeValue(container.Ports); ports != "" {
		attributes["ports"] = ports
	}

	return attributes
}

func forwardRuntimeEvents(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	registry *netlinkRegistry,
	runtimeEvents <-chan clabruntime.ContainerEvent,
	runtimeErrs <-chan error,
	eventSink chan<- aggregatedEvent,
	errSink chan<- error,
) {
	defer close(errSink)

	sendErr := func(err error) {
		select {
		case errSink <- err:
		case <-ctx.Done():
		}
	}

	for {
		select {
		case <-ctx.Done():
			return
		case err, ok := <-runtimeErrs:
			if !ok {
				return
			}

			if err != nil && !errors.Is(err, context.Canceled) {
				sendErr(err)

				return
			}
		case ev, ok := <-runtimeEvents:
			if !ok {
				return
			}

			registry.HandleContainerEvent(runtime, ev)

			aggregated := aggregatedEventFromContainerEvent(ctx, runtime, ev)
			select {
			case eventSink <- aggregated:
			case <-ctx.Done():
				return
			}
		}
	}
}

func aggregatedEventFromContainerEvent(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	ev clabruntime.ContainerEvent,
) aggregatedEvent {
	ts := ev.Timestamp
	if ts.IsZero() {
		ts = time.Now()
	}

	attributes := cloneStringMap(ev.Attributes)

	actorFullID := ev.ActorFullID
	if actorFullID == "" {
		actorFullID = ev.ActorID
	}

	actorName := ev.ActorName
	if actorName == "" && attributes != nil {
		actorName = attributes["name"]
	}

	attributes = ensureContainerAttributes(ctx, runtime, attributes, actorFullID, actorName)

	short := ev.ActorID
	if short == "" {
		short = actorFullID
	}

	action := strings.ToLower(ev.Action)
	if action == "" {
		action = ev.Action
	}

	eventType := strings.ToLower(ev.Type)
	if eventType == "" {
		eventType = ev.Type
	}

	return aggregatedEvent{
		Timestamp:   ts,
		Type:        eventType,
		Action:      action,
		ActorID:     clabutils.ShortID(short),
		ActorName:   actorName,
		ActorFullID: actorFullID,
		Attributes:  attributes,
	}
}

func ensureContainerAttributes(
	ctx context.Context,
	runtime clabruntime.ContainerRuntime,
	attributes map[string]string,
	actorFullID, actorName string,
) map[string]string {
	if runtime == nil {
		return attributes
	}

	hasIPv4 := attributes != nil && attributes["mgmt_ipv4"] != ""
	hasIPv6 := attributes != nil && attributes["mgmt_ipv6"] != ""
	hasPorts := attributes != nil && attributes["ports"] != ""

	if hasIPv4 && hasIPv6 && hasPorts {
		return attributes
	}

	filters := make([]*clabtypes.GenericFilter, 0, 2)

	if actorName == "" && attributes != nil {
		actorName = attributes["name"]
	}

	if actorName != "" {
		filters = append(filters, &clabtypes.GenericFilter{FilterType: "name", Match: actorName})
	}

	if actorFullID != "" {
		filters = append(filters, &clabtypes.GenericFilter{FilterType: "id", Match: actorFullID})
	}

	if len(filters) == 0 {
		return attributes
	}

	containers, err := runtime.ListContainers(ctx, filters)
	if err != nil {
		log.Debugf("failed to resolve container for event: %v", err)

		return attributes
	}

	container := selectContainerForEvent(containers, actorFullID, actorName)
	if container == nil {
		return attributes
	}

	if attributes == nil {
		attributes = make(map[string]string)
	}

	if !hasIPv4 {
		if ipv4 := container.GetContainerIPv4(); ipv4 != "" && ipv4 != clabconstants.NotApplicable {
			attributes["mgmt_ipv4"] = ipv4
		}
	}

	if !hasIPv6 {
		if ipv6 := container.GetContainerIPv6(); ipv6 != "" && ipv6 != clabconstants.NotApplicable {
			attributes["mgmt_ipv6"] = ipv6
		}
	}

	if !hasPorts {
		if ports := exposedPortsAttributeValue(container.Ports); ports != "" {
			attributes["ports"] = ports
		}
	}

	if len(attributes) == 0 {
		return nil
	}

	return attributes
}

func selectContainerForEvent(
	containers []clabruntime.GenericContainer,
	actorFullID, actorName string,
) *clabruntime.GenericContainer {
	if len(containers) == 0 {
		return nil
	}

	if actorFullID != "" {
		for idx := range containers {
			container := &containers[idx]

			switch {
			case container.ID == actorFullID:
				return container
			case strings.HasPrefix(container.ID, actorFullID):
				return container
			case container.ShortID == actorFullID:
				return container
			}
		}
	}

	if actorName != "" {
		for idx := range containers {
			container := &containers[idx]

			for _, name := range container.Names {
				if name == actorName {
					return container
				}
			}
		}
	}

	return &containers[0]
}

func emitContainerSnapshots(
	ctx context.Context,
	containers []clabruntime.GenericContainer,
	sink chan<- aggregatedEvent,
) {
	for idx := range containers {
		container := containers[idx]
		if !isRunningContainer(&container) && !strings.EqualFold(container.State, "exited") {
			continue
		}

		event := aggregatedEventFromContainerSnapshot(&container)
		if event.ActorID == "" && event.ActorName == "" {
			continue
		}

		select {
		case sink <- event:
		case <-ctx.Done():
			return
		}
	}
}

func aggregatedEventFromContainerSnapshot(
	container *clabruntime.GenericContainer,
) aggregatedEvent {
	if container == nil {
		return aggregatedEvent{}
	}

	state := strings.ToLower(container.State)

	short := container.ShortID
	if short == "" {
		short = clabutils.ShortID(container.ID)
	}

	attributes := containerAttributes(container)

	if _, ok := attributes["origin"]; !ok {
		attributes["origin"] = "snapshot"
	}

	if container.Status != "" {
		attributes["status"] = container.Status
	}

	if state != "" {
		attributes["state"] = state
	}

	if container.NetworkName != "" {
		attributes["network"] = container.NetworkName
	}

	if len(attributes) == 0 {
		attributes = nil
	}

	actorName := firstContainerName(container)

	action := state
	if action == "" {
		action = "snapshot"
	}

	return aggregatedEvent{
		Timestamp:   time.Now(),
		Type:        "container",
		Action:      action,
		ActorID:     clabutils.ShortID(short),
		ActorName:   actorName,
		ActorFullID: container.ID,
		Attributes:  attributes,
	}
}

func cloneStringMap(input map[string]string) map[string]string {
	if len(input) == 0 {
		return nil
	}

	result := make(map[string]string, len(input))
	for k, v := range input {
		result[k] = v
	}

	return result
}

func isRunningContainer(container *clabruntime.GenericContainer) bool {
	if container == nil {
		return false
	}

	return strings.EqualFold(container.State, "running")
}

func exposedPortsAttributeValue(ports []*clabtypes.GenericPortBinding) string {
	if len(ports) == 0 {
		return ""
	}

	sortedPorts := make([]*clabtypes.GenericPortBinding, 0, len(ports))
	for idx := range ports {
		if ports[idx] != nil {
			sortedPorts = append(sortedPorts, ports[idx])
		}
	}

	if len(sortedPorts) == 0 {
		return ""
	}

	sort.Slice(sortedPorts, func(i, j int) bool {
		left := sortedPorts[i]
		right := sortedPorts[j]

		switch {
		case left.ContainerPort != right.ContainerPort:
			return left.ContainerPort < right.ContainerPort
		case left.Protocol != right.Protocol:
			return left.Protocol < right.Protocol
		case left.HostPort != right.HostPort:
			return left.HostPort < right.HostPort
		default:
			return left.HostIP < right.HostIP
		}
	})

	result := make([]string, 0, len(sortedPorts))
	for idx := range sortedPorts {
		formatted := formatExposedPort(sortedPorts[idx])
		if formatted != "" {
			result = append(result, formatted)
		}
	}

	if len(result) == 0 {
		return ""
	}

	return strings.Join(result, ";")
}

func formatExposedPort(port *clabtypes.GenericPortBinding) string {
	if port == nil {
		return ""
	}

	proto := strings.TrimSpace(strings.ToLower(port.Protocol))
	protoSuffix := ""
	if proto != "" {
		protoSuffix = "/" + proto
	}

	if port.HostPort > 0 {
		hostIP := port.HostIP
		if hostIP == "" {
			hostIP = "0.0.0.0"
		}

		if strings.Contains(hostIP, ":") {
			hostIP = fmt.Sprintf("[%s]", hostIP)
		}

		if port.ContainerPort > 0 {
			return fmt.Sprintf(
				"%s:%d%s->%d",
				hostIP,
				port.HostPort,
				protoSuffix,
				port.ContainerPort,
			)
		}

		return fmt.Sprintf("%s:%d%s", hostIP, port.HostPort, protoSuffix)
	}

	if port.ContainerPort <= 0 {
		return ""
	}

	return fmt.Sprintf("%d%s", port.ContainerPort, protoSuffix)
}

package clabernetes

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/charmbracelet/log"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	"k8s.io/apimachinery/pkg/fields"
	"k8s.io/apimachinery/pkg/labels"
	"k8s.io/apimachinery/pkg/watch"
)

func (r *Runtime) StreamEvents(
	ctx context.Context,
	req clablabruntime.EventStreamRequest,
) (<-chan clablabruntime.Event, <-chan error, error) {
	r, connErr := r.connect(ctx, req.Identity)
	if connErr != nil {
		return nil, nil, connErr
	}

	scope, err := r.eventScopeFor(req)
	if err != nil {
		return nil, nil, err
	}

	events := make(chan clablabruntime.Event, 128)
	errs := make(chan error, 4)
	// changed carries the labs whose Topology, Nodes or pods changed; the container tracker
	// reads them again and reports what changed for their nodes.
	changed := make(chan labRef, 256)

	go r.trackContainers(ctx, scope, req.IncludeInitialState, changed, events, errs)

	// Interface state events are always reported, like the netlink-backed events of the local
	// runtimes; statistics only on request. Both come from the same exec per node.
	go r.pollInterfaces(ctx, scope, interfacePollOptions{
		interval:            req.StatsInterval,
		includeStats:        req.IncludeInterfaceStats,
		includeInitialState: req.IncludeInitialState,
	}, events)

	go r.watchTopologies(ctx, scope, changed, events, errs)
	go r.watchNodes(ctx, scope, changed, errs)
	go r.watchPods(ctx, scope, changed, errs)

	return events, errs, nil
}

// labRef names a lab in a namespace.
type labRef struct {
	namespace string
	lab       string
}

func sendChangedLab(ctx context.Context, changed chan<- labRef, ref labRef) {
	if ref.lab == "" {
		return
	}

	select {
	case changed <- ref:
	case <-ctx.Done():
	}
}

// eventScope is the namespace and, optionally, the single lab an event stream covers.
type eventScope struct {
	namespace string
	lab       string
}

func (r *Runtime) eventScopeFor(req clablabruntime.EventStreamRequest) (eventScope, error) {
	if req.Name != "" {
		namespace, err := r.namespaceForLab(req.Name, req.Namespace)
		if err != nil {
			return eventScope{}, err
		}

		return eventScope{namespace: namespace, lab: req.Name}, nil
	}

	return eventScope{namespace: r.listNamespace(req.Namespace, req.AllNamespaces)}, nil
}

// labelSelector selects the lab-owned resources of the scope.
func (s eventScope) labelSelector() string {
	if s.lab != "" {
		return labels.Set{labelTopologyOwner: s.lab}.String()
	}

	return labelTopologyOwner
}

// topologyListOptions selects the Topology resources of the scope.
func (s eventScope) topologyListOptions() metav1.ListOptions {
	if s.lab != "" {
		return metav1.ListOptions{
			FieldSelector: fields.OneTermEqualSelector("metadata.name", s.lab).String(),
		}
	}

	return metav1.ListOptions{}
}

// labStates lists the labs of the scope.
func (r *Runtime) labStates(
	ctx context.Context,
	scope eventScope,
) ([]*clablabruntime.LabState, error) {
	if scope.lab != "" {
		state, err := r.Inspect(ctx, clablabruntime.InspectRequest{
			Name:      scope.lab,
			Namespace: scope.namespace,
		})
		if err != nil {
			// A lab that is not deployed yet has no state; its resources show up through
			// the watches once it is.
			var notFound *labNotFoundError
			if errors.As(err, &notFound) {
				return nil, nil
			}

			return nil, err
		}

		return []*clablabruntime.LabState{state}, nil
	}

	return r.List(ctx, clablabruntime.ListRequest{
		Namespace:     scope.namespace,
		AllNamespaces: scope.namespace == metav1.NamespaceAll,
	})
}

func (r *Runtime) watchNodes(
	ctx context.Context,
	scope eventScope,
	changed chan<- labRef,
	errSink chan<- error,
) {
	resource := r.client.Resource(nodeGVR).Namespace(scope.namespace)

	for {
		watcher, err := resource.Watch(ctx, metav1.ListOptions{
			LabelSelector: scope.labelSelector(),
		})
		if err != nil {
			if ctx.Err() != nil {
				return
			}

			sendEventError(ctx, errSink, fmt.Errorf("failed to watch c9s nodes: %w", err))
			return
		}

		if !r.forwardNodeWatch(ctx, watcher, changed, errSink) {
			return
		}

		if !sleepContext(ctx, pollInterval) {
			return
		}
	}
}

// forwardNodeWatch reports the lab of every changed Node to the container tracker.
func (r *Runtime) forwardNodeWatch(
	ctx context.Context,
	watcher watch.Interface,
	changed chan<- labRef,
	errSink chan<- error,
) bool {
	defer watcher.Stop()

	for {
		select {
		case <-ctx.Done():
			return false
		case ev, ok := <-watcher.ResultChan():
			if !ok {
				log.Debug("c9s node watch closed, reconnecting")
				return true
			}
			if ev.Type == watch.Error {
				sendEventError(ctx, errSink, fmt.Errorf("c9s node watch returned an error"))
				return false
			}

			node, ok := ev.Object.(*unstructured.Unstructured)
			if !ok {
				continue
			}

			sendChangedLab(ctx, changed, labRef{
				namespace: node.GetNamespace(),
				lab:       node.GetLabels()[labelTopologyOwner],
			})
		}
	}
}

func (r *Runtime) watchTopologies(
	ctx context.Context,
	scope eventScope,
	changed chan<- labRef,
	eventSink chan<- clablabruntime.Event,
	errSink chan<- error,
) {
	resource := r.client.Resource(topologyGVR).Namespace(scope.namespace)

	for {
		watcher, err := resource.Watch(ctx, scope.topologyListOptions())
		if err != nil {
			if ctx.Err() != nil {
				return
			}

			sendEventError(
				ctx,
				errSink,
				fmt.Errorf("failed to watch clabernetes topologies: %w", err),
			)
			return
		}

		if !r.forwardTopologyWatch(ctx, scope.namespace, watcher, changed, eventSink, errSink) {
			return
		}

		if !sleepContext(ctx, pollInterval) {
			return
		}
	}
}

// forwardTopologyWatch reports Topology changes as topology events, which only c9s has, and
// reports the lab to the container tracker.
func (r *Runtime) forwardTopologyWatch(
	ctx context.Context,
	namespace string,
	watcher watch.Interface,
	changed chan<- labRef,
	eventSink chan<- clablabruntime.Event,
	errSink chan<- error,
) bool {
	defer watcher.Stop()

	for {
		select {
		case <-ctx.Done():
			return false
		case ev, ok := <-watcher.ResultChan():
			if !ok {
				log.Debug("C9s topology watch closed, reconnecting")
				return true
			}
			if ev.Type == watch.Error {
				sendEventError(
					ctx,
					errSink,
					fmt.Errorf("clabernetes topology watch returned an error"),
				)
				return false
			}

			obj, ok := ev.Object.(*unstructured.Unstructured)
			if !ok {
				continue
			}

			state := stateFromTopology(obj, namespace)
			r.sendEvent(ctx, eventSink, clablabruntime.Event{
				Timestamp: time.Now(),
				Type:      "topology",
				Action:    strings.ToLower(string(ev.Type)),
				ActorID:   fmt.Sprintf("%s/%s", state.Namespace, state.Name),
				ActorName: state.Name,
				Attributes: map[string]string{
					"namespace": state.Namespace,
					"lab":       state.Name,
					"state":     state.State,
					"ready":     fmt.Sprintf("%t", state.Ready),
				},
			})
			sendChangedLab(ctx, changed, labRef{namespace: state.Namespace, lab: state.Name})
		}
	}
}

func (r *Runtime) watchPods(
	ctx context.Context,
	scope eventScope,
	changed chan<- labRef,
	errSink chan<- error,
) {
	for {
		watcher, err := r.kubeClient.CoreV1().Pods(scope.namespace).Watch(ctx, metav1.ListOptions{
			LabelSelector: scope.labelSelector(),
		})
		if err != nil {
			if ctx.Err() != nil {
				return
			}

			sendEventError(ctx, errSink, fmt.Errorf(
				"failed to watch clabernetes pods: %w", err))
			return
		}

		if !r.forwardPodWatch(ctx, watcher, changed, errSink) {
			return
		}

		if !sleepContext(ctx, pollInterval) {
			return
		}
	}
}

// forwardPodWatch reports the lab of every changed pod to the container tracker.
func (r *Runtime) forwardPodWatch(
	ctx context.Context,
	watcher watch.Interface,
	changed chan<- labRef,
	errSink chan<- error,
) bool {
	defer watcher.Stop()

	for {
		select {
		case <-ctx.Done():
			return false
		case ev, ok := <-watcher.ResultChan():
			if !ok {
				log.Debug("C9s pod watch closed, reconnecting")
				return true
			}
			if ev.Type == watch.Error {
				sendEventError(ctx, errSink, fmt.Errorf(
					"clabernetes pod watch returned an error"))
				return false
			}

			pod, ok := ev.Object.(*corev1.Pod)
			if !ok {
				continue
			}

			sendChangedLab(ctx, changed, labRef{
				namespace: pod.Namespace,
				lab:       pod.Labels[labelTopologyOwner],
			})
		}
	}
}

func sleepContext(ctx context.Context, d time.Duration) bool {
	timer := time.NewTimer(d)
	defer timer.Stop()

	select {
	case <-timer.C:
		return true
	case <-ctx.Done():
		return false
	}
}

func (r *Runtime) sendEvent(
	ctx context.Context,
	eventSink chan<- clablabruntime.Event,
	event clablabruntime.Event,
) {
	select {
	case eventSink <- event:
	case <-ctx.Done():
	}
}

func sendEventError(ctx context.Context, errSink chan<- error, err error) {
	select {
	case errSink <- err:
	case <-ctx.Done():
	}
}

package clabernetes

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/charmbracelet/log"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
)

// Container event actions, as the Docker runtime reports them.
const (
	containerActionCreate        = "create"
	containerActionStart         = "start"
	containerActionKill          = "kill"
	containerActionStop          = "stop"
	containerActionDie           = "die"
	containerActionDestroy       = "destroy"
	containerActionHealthPrefix  = "health_status: "
	containerEventSignalSIGTERM  = "15"
	containerRefreshDelay        = 200 * time.Millisecond
	containerRefreshRetryDelay   = pollInterval
	containerEventAttributeState = "state"
)

// trackedContainer is the last reported container state of a node.
type trackedContainer struct {
	ref    labRef
	state  string
	health string
	pod    string
	// lab and node are the last observation, which a removed node is described with.
	lab  *clablabruntime.LabState
	node clablabruntime.NodeState
}

// containerTracker turns the node states of the labs in an event scope into the container
// events the Docker runtime emits for the same lifecycle: create and start when a node's pod
// starts, kill, stop and die when it stops (on request, or between the pods of a restart),
// destroy when the node is removed, and health_status as its device becomes ready.
type containerTracker struct {
	r     *Runtime
	sink  chan<- clablabruntime.Event
	nodes map[string]*trackedContainer
}

// trackContainers reports the container events of a scope. It reads the labs once, reporting
// them as a snapshot when the stream includes the initial state, and then reads a lab again
// whenever its Topology, Nodes or pods change. Changes that arrive together are read once.
func (r *Runtime) trackContainers(
	ctx context.Context,
	scope eventScope,
	includeInitialState bool,
	changed <-chan labRef,
	eventSink chan<- clablabruntime.Event,
	errSink chan<- error,
) {
	tracker := &containerTracker{r: r, sink: eventSink, nodes: map[string]*trackedContainer{}}

	states, err := r.labStates(ctx, scope)
	if err != nil {
		sendEventError(ctx, errSink, err)
		return
	}
	for _, state := range states {
		tracker.observeLab(ctx, labRef{namespace: state.Namespace, lab: state.Name}, state,
			&observeSeed{snapshot: includeInitialState})
	}

	pending := map[labRef]bool{}
	timer := time.NewTimer(time.Hour)
	timer.Stop()
	defer timer.Stop()
	armed := false
	arm := func(delay time.Duration) {
		if !armed {
			timer.Reset(delay)
			armed = true
		}
	}

	for {
		select {
		case <-ctx.Done():
			return
		case ref := <-changed:
			pending[ref] = true
			arm(containerRefreshDelay)
		case <-timer.C:
			armed = false
			refs := pending
			pending = map[labRef]bool{}
			for ref := range refs {
				if !tracker.refresh(ctx, ref) {
					pending[ref] = true
				}
			}
			if len(pending) != 0 {
				arm(containerRefreshRetryDelay)
			}
		}
	}
}

// observeSeed marks the first observation of a stream: it records the node states without
// reporting changes, and reports them as a snapshot when asked to.
type observeSeed struct {
	snapshot bool
}

// refresh reads a lab again and reports what changed for its nodes. A lab that is gone reports
// its nodes as destroyed. It returns false when the lab could not be read.
func (t *containerTracker) refresh(ctx context.Context, ref labRef) bool {
	state, err := t.r.Inspect(ctx, clablabruntime.InspectRequest{
		Name:      ref.lab,
		Namespace: ref.namespace,
	})
	if err != nil {
		var notFound *labNotFoundError
		if !errors.As(err, &notFound) {
			if ctx.Err() == nil {
				log.Debug("Failed to read a C9s lab for container events",
					"namespace", ref.namespace, "lab", ref.lab, "error", err)
			}

			return ctx.Err() != nil
		}
		state = nil
	}

	t.observeLab(ctx, ref, state, nil)

	return true
}

// observeLab compares the nodes of a lab with what was reported before and reports the
// difference. A nil state removes every node of the lab.
func (t *containerTracker) observeLab(
	ctx context.Context,
	ref labRef,
	state *clablabruntime.LabState,
	seed *observeSeed,
) {
	seen := map[string]bool{}
	if state != nil {
		for idx := range state.Nodes {
			key := c9sNodeKey(state.Namespace, state.Name, state.Nodes[idx].Name)
			seen[key] = true
			t.observeNode(ctx, ref, state, state.Nodes[idx], seed)
		}
	}

	for key, tracked := range t.nodes {
		if tracked.ref != ref || seen[key] {
			continue
		}

		for _, action := range containerRemovalActions(tracked) {
			t.emit(ctx, tracked.lab, tracked.node, action, nil)
		}
		delete(t.nodes, key)
	}
}

func (t *containerTracker) observeNode(
	ctx context.Context,
	ref labRef,
	state *clablabruntime.LabState,
	node clablabruntime.NodeState,
	seed *observeSeed,
) {
	key := c9sNodeKey(state.Namespace, state.Name, node.Name)
	previous := t.nodes[key]
	if node.ContainerState == "" {
		node.ContainerState = clablabruntime.ContainerStateCreated
	}
	next := &trackedContainer{
		ref:   ref,
		state: node.ContainerState,
		pod:   node.Pod,
		lab:   state,
		node:  node,
	}
	next.health = containerHealth(previous, next, node.Health)
	t.nodes[key] = next

	if seed != nil {
		if seed.snapshot {
			t.emit(ctx, state, node, next.state, map[string]string{
				"origin": clablabruntime.EventOriginSnapshot,
			})
		}

		return
	}

	for _, action := range containerTransitionActions(previous, next) {
		t.emit(ctx, state, node, action, nil)
	}
}

// containerHealth is the health a running node reports: a node that was healthy and is not
// ready anymore in the same pod is unhealthy, as a container whose healthcheck starts failing.
func containerHealth(previous, next *trackedContainer, health string) string {
	if next.state != clablabruntime.ContainerStateRunning {
		return ""
	}
	if health == "" {
		health = clablabruntime.ContainerHealthStarting
	}
	if health == clablabruntime.ContainerHealthStarting && previous != nil &&
		previous.state == clablabruntime.ContainerStateRunning && previous.pod == next.pod &&
		(previous.health == clablabruntime.ContainerHealthHealthy ||
			previous.health == clablabruntime.ContainerHealthUnhealthy) {
		return clablabruntime.ContainerHealthUnhealthy
	}

	return health
}

// containerTransitionActions are the container event actions Docker reports when a container
// goes from the previous to the next state:
//
//	new node            create (+ start when it runs, + stop when it is already stopped)
//	created -> running  start
//	exited  -> running  start
//	running -> exited   kill, stop, die (stop, or the old pod of a restart ending)
//	running -> created  kill, stop, die (the replacement pod of a restart not running yet)
//	running, new pod    kill, stop, die, start (restart)
//	created -> exited   stop
//
// A started node also reports its health (health_status: starting or healthy), and a running
// node reports health changes, like a container with a healthcheck.
func containerTransitionActions(previous, next *trackedContainer) []string {
	const (
		created = clablabruntime.ContainerStateCreated
		running = clablabruntime.ContainerStateRunning
		exited  = clablabruntime.ContainerStateExited
	)

	var actions []string
	previousState := ""
	if previous != nil {
		previousState = previous.state
	}

	switch {
	case previous == nil:
		actions = append(actions, containerActionCreate)
		switch next.state {
		case running:
			actions = append(actions, containerActionStart)
		case exited:
			actions = append(actions, containerActionStop)
		}
	case previousState == running && next.state == running && previous.pod != next.pod:
		actions = append(actions, containerActionKill, containerActionStop, containerActionDie,
			containerActionStart)
	case previousState == running && next.state != running:
		actions = append(actions, containerActionKill, containerActionStop, containerActionDie)
	case previousState != running && next.state == running:
		actions = append(actions, containerActionStart)
	case previousState == created && next.state == exited:
		actions = append(actions, containerActionStop)
	}

	if next.state != running {
		return actions
	}

	started := len(actions) != 0 && actions[len(actions)-1] == containerActionStart
	if !started && previous != nil && previous.health == next.health {
		return actions
	}
	if next.health == clablabruntime.ContainerHealthStarting && !started {
		return actions
	}

	return append(actions, containerActionHealthPrefix+next.health)
}

// containerRemovalActions are the actions Docker reports when a container is removed: a running
// one is killed and dies first.
func containerRemovalActions(previous *trackedContainer) []string {
	if previous.state == clablabruntime.ContainerStateRunning {
		return []string{containerActionKill, containerActionDie, containerActionDestroy}
	}

	return []string{containerActionDestroy}
}

// containerActionState is the container state after an action, which every container event
// reports in its state attribute.
func containerActionState(action, snapshotState string) string {
	switch action {
	case containerActionCreate:
		return clablabruntime.ContainerStateCreated
	case containerActionStop, containerActionDie, containerActionDestroy:
		return clablabruntime.ContainerStateExited
	case containerActionStart, containerActionKill:
		return clablabruntime.ContainerStateRunning
	}
	if strings.HasPrefix(action, containerActionHealthPrefix) {
		return clablabruntime.ContainerStateRunning
	}

	return snapshotState
}

func (t *containerTracker) emit(
	ctx context.Context,
	state *clablabruntime.LabState,
	node clablabruntime.NodeState,
	action string,
	extra map[string]string,
) {
	t.r.sendEvent(ctx, t.sink, c9sContainerEvent(state, node, action, extra))
}

// c9sContainerEvent is a container event of a node. The actor is the node, as for its interface
// events; its ID is the container_id inspect reports. Lab and Node let the events command
// describe the node with the attributes inspect and the Docker runtime report.
func c9sContainerEvent(
	state *clablabruntime.LabState,
	node clablabruntime.NodeState,
	action string,
	extra map[string]string,
) clablabruntime.Event {
	key := c9sNodeKey(state.Namespace, state.Name, node.Name)
	attributes := map[string]string{
		"namespace":                  state.Namespace,
		"lab":                        state.Name,
		"node":                       node.Name,
		containerEventAttributeState: containerActionState(action, node.ContainerState),
	}
	if node.Pod != "" {
		attributes["pod"] = node.Pod
	}
	if action == containerActionKill {
		// Kubernetes stops a pod's containers with SIGTERM.
		attributes["signal"] = containerEventSignalSIGTERM
	}
	for k, v := range extra {
		attributes[k] = v
	}

	nodeCopy := node

	return clablabruntime.Event{
		Timestamp:   time.Now(),
		Type:        clablabruntime.EventTypeContainer,
		Action:      action,
		ActorID:     key,
		ActorName:   fmt.Sprintf("%s-%s", state.Name, node.Name),
		ActorFullID: key,
		Attributes:  attributes,
		Lab:         state,
		Node:        &nodeCopy,
	}
}

package clabernetes

import (
	"context"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/charmbracelet/log"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

const (
	// interfaceSysfsMarker separates the /proc/net/dev counters from the sysfs interface
	// attributes in the output of interfaceSampleScript.
	interfaceSysfsMarker = "@@clab-sysfs"
	// interfaceSampleScript reads the interface counters and, per interface, the sysfs
	// attributes the interface state events carry, in one exec:
	// name, ifindex, mtu, address, operstate, flags and ifalias, tab separated.
	interfaceSampleScript = `cat /proc/net/dev; echo ` + interfaceSysfsMarker + `; ` +
		`for d in /sys/class/net/*; do [ -e "$d/operstate" ] || continue; ` +
		`printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "${d##*/}" "$(cat "$d/ifindex")" ` +
		`"$(cat "$d/mtu")" "$(cat "$d/address")" "$(cat "$d/operstate")" ` +
		`"$(cat "$d/flags")" "$(cat "$d/ifalias")"; done 2>/dev/null`

	// interfaceSampleWorkers bounds the concurrent execs of one sampling round.
	interfaceSampleWorkers = 16

	// managementInterface is a node's management interface in its pod, the interface the
	// clabernetes planner gives the management address by default. It has the name the
	// management interface has in a container of the local runtimes.
	managementInterface = "eth0"
	// loopbackInterface is reported like the local runtimes report it.
	loopbackInterface = "lo"
	// clabernetesAliasPrefix starts the interface aliases clabernetes marks its own interfaces
	// and the lab links it wires with. They are not the topology's names, so they are not
	// reported.
	clabernetesAliasPrefix = "c9s:"
	// zeroMAC is the hardware address sysfs reports for interfaces without one (loopback).
	zeroMAC = "00:00:00:00:00:00"

	// Interface event actions and link types, as the local runtimes report them.
	interfaceActionSnapshot = "snapshot"
	interfaceActionCreate   = "create"
	interfaceActionUpdate   = "update"
	interfaceActionDelete   = "delete"
	interfaceActionStats    = "stats"
	interfaceTypeVeth       = "veth"
	interfaceTypeDevice     = "device"

	// shell exit codes of a command that cannot be found or executed.
	exitCommandNotExecutable = 126
	exitCommandNotFound      = 127
)

type interfacePollOptions struct {
	interval            time.Duration
	includeStats        bool
	includeInitialState bool
}

type c9sIfaceStats struct {
	Name      string
	RxBytes   uint64
	RxPackets uint64
	TxBytes   uint64
	TxPackets uint64
}

type c9sIfaceStatsSample struct {
	Stats     c9sIfaceStats
	Timestamp time.Time
}

// c9sIfaceState is the sysfs view of one interface in a device container.
type c9sIfaceState struct {
	Name      string
	Index     int
	MTU       int
	MAC       string
	OperState string
	Flags     uint64
	Alias     string
}

// trackedNode remembers the interfaces last reported for a node, so their changes and their
// removal can be reported, also when the node stops running.
type trackedNode struct {
	lab    *clablabruntime.LabState
	node   clablabruntime.NodeState
	ifaces map[string]clablabruntime.InterfaceEventData
}

type interfaceSampleTarget struct {
	state *clablabruntime.LabState
	node  clablabruntime.NodeState
	pod   *corev1.Pod
}

type interfaceSample struct {
	target    interfaceSampleTarget
	stats     []c9sIfaceStats
	ifaces    []c9sIfaceState
	hasStates bool
	// links are the node's lab link interfaces as clabwire lists them.
	links     []clabwireInterface
	timestamp time.Time
	err       error
}

// podInterfaceListing is the clabwire interface listing of a pod, per node. It is listed again
// when the pod's interfaces change.
type podInterfaceListing struct {
	names  string
	byNode map[string][]clabwireInterface
}

// interfacePoller samples the interfaces of every running node in an event scope and turns the
// samples into interface events. It reports the interfaces a container of the local runtimes
// has for the same node: the node's lab link interfaces, with the names and aliases clabwire
// lists for them, the management interface and loopback. The pod's own interfaces (the pod
// network, clabernetes' interposition and link transport interfaces) are not reported.
type interfacePoller struct {
	r     *Runtime
	scope eventScope
	opts  interfacePollOptions
	sink  chan<- clablabruntime.Event

	statsSamples map[string]c9sIfaceStatsSample
	nodes        map[string]*trackedNode

	noShellMu sync.Mutex
	// noShell holds the pods whose device container has no shell; they are sampled with a
	// plain cat of /proc/net/dev and report statistics without interface state.
	noShell map[string]bool

	listingsMu sync.Mutex
	// listings holds the clabwire interface listing per pod (namespace/pod).
	listings map[string]*podInterfaceListing

	firstRound bool
}

func (r *Runtime) pollInterfaces(
	ctx context.Context,
	scope eventScope,
	opts interfacePollOptions,
	eventSink chan<- clablabruntime.Event,
) {
	if opts.interval <= 0 {
		opts.interval = time.Second
	}

	poller := newInterfacePoller(r, scope, opts, eventSink)
	poller.round(ctx)

	ticker := time.NewTicker(opts.interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			poller.round(ctx)
		}
	}
}

func newInterfacePoller(
	r *Runtime,
	scope eventScope,
	opts interfacePollOptions,
	eventSink chan<- clablabruntime.Event,
) *interfacePoller {
	return &interfacePoller{
		r:            r,
		scope:        scope,
		opts:         opts,
		sink:         eventSink,
		statsSamples: map[string]c9sIfaceStatsSample{},
		nodes:        map[string]*trackedNode{},
		noShell:      map[string]bool{},
		listings:     map[string]*podInterfaceListing{},
		firstRound:   true,
	}
}

func (p *interfacePoller) round(ctx context.Context) {
	defer func() { p.firstRound = false }()

	states, err := p.r.labStates(ctx, p.scope)
	if err != nil {
		log.Debug("failed to list C9s labs for interface events", "error", err)
		return
	}

	running := map[string]bool{}
	pods := map[string]bool{}
	var targets []interfaceSampleTarget
	for _, state := range states {
		for _, node := range state.Nodes {
			if node.ContainerState != clablabruntime.ContainerStateRunning || node.Pod == "" ||
				node.Container == "" {
				continue
			}

			running[c9sNodeKey(state.Namespace, state.Name, node.Name)] = true
			pods[state.Namespace+"/"+node.Pod] = true
			targets = append(targets, interfaceSampleTarget{
				state: state,
				node:  node,
				pod: &corev1.Pod{ObjectMeta: metav1.ObjectMeta{
					Name:      node.Pod,
					Namespace: state.Namespace,
				}},
			})
		}
	}

	for _, sample := range p.sampleAll(ctx, targets) {
		if ctx.Err() != nil {
			return
		}
		if sample.err != nil {
			log.Debug("failed to sample C9s interfaces",
				"namespace", sample.target.state.Namespace,
				"lab", sample.target.state.Name,
				"node", sample.target.node.Name,
				"error", sample.err,
			)

			continue
		}

		p.processSample(ctx, sample)
	}

	p.retireStoppedNodes(ctx, running)
	p.forgetListings(pods)
}

// retireStoppedNodes reports the interfaces of nodes that stopped running, or were removed, as
// deleted: they are gone with the node's pod.
func (p *interfacePoller) retireStoppedNodes(ctx context.Context, running map[string]bool) {
	for key, tracked := range p.nodes {
		if running[key] {
			continue
		}

		for _, name := range sortedInterfaceNames(tracked.ifaces) {
			p.emit(ctx, tracked, interfaceActionDelete, tracked.ifaces[name], time.Now())
			p.forgetStats(tracked, name)
		}
		delete(p.nodes, key)
	}
}

// forgetListings drops the interface listings of pods that are gone.
func (p *interfacePoller) forgetListings(pods map[string]bool) {
	p.listingsMu.Lock()
	defer p.listingsMu.Unlock()

	for key := range p.listings {
		if !pods[key] {
			delete(p.listings, key)
		}
	}
}

func (p *interfacePoller) sampleAll(
	ctx context.Context,
	targets []interfaceSampleTarget,
) []interfaceSample {
	samples := make([]interfaceSample, len(targets))

	var wg sync.WaitGroup
	sem := make(chan struct{}, interfaceSampleWorkers)
	for idx := range targets {
		wg.Add(1)
		sem <- struct{}{}
		go func(idx int) {
			defer wg.Done()
			defer func() { <-sem }()

			samples[idx] = p.sample(ctx, targets[idx])
		}(idx)
	}
	wg.Wait()

	return samples
}

func (p *interfacePoller) sample(
	ctx context.Context,
	target interfaceSampleTarget,
) interfaceSample {
	sample := interfaceSample{target: target}
	podName := target.pod.Name

	p.noShellMu.Lock()
	noShell := p.noShell[podName]
	p.noShellMu.Unlock()

	command := []string{"sh", "-c", interfaceSampleScript}
	if noShell {
		command = []string{"cat", "/proc/net/dev"}
	}

	stdout, stderr, rc, err := p.r.execInPod(ctx, target.pod, target.node.Container, command)
	if !noShell && commandNotExecutable(rc, err) {
		p.noShellMu.Lock()
		p.noShell[podName] = true
		p.noShellMu.Unlock()

		log.Debug("C9s device container has no shell; reporting interface statistics only",
			"namespace", target.state.Namespace,
			"lab", target.state.Name,
			"node", target.node.Name,
		)

		stdout, stderr, rc, err = p.r.execInPod(ctx, target.pod, target.node.Container,
			[]string{"cat", "/proc/net/dev"})
	}

	sample.timestamp = time.Now()
	switch {
	case err != nil:
		sample.err = err
	case rc != 0:
		sample.err = fmt.Errorf("exit code %d: %s", rc, strings.TrimSpace(string(stderr)))
	default:
		sample.stats, sample.ifaces, sample.hasStates, sample.err = parseInterfaceSample(stdout)
	}
	if sample.err != nil {
		return sample
	}

	sample.links, sample.err = p.nodeLinks(ctx, target, sampledInterfaceNames(sample))

	return sample
}

// sampledInterfaceNames lists the interface names a sample saw, sorted and comma-joined.
func sampledInterfaceNames(sample interfaceSample) string {
	names := make([]string, 0, len(sample.stats)+len(sample.ifaces))
	seen := map[string]bool{}
	for _, iface := range sample.ifaces {
		if !seen[iface.Name] {
			seen[iface.Name] = true
			names = append(names, iface.Name)
		}
	}
	for _, stat := range sample.stats {
		if !seen[stat.Name] {
			seen[stat.Name] = true
			names = append(names, stat.Name)
		}
	}
	sort.Strings(names)

	return strings.Join(names, ",")
}

// nodeLinks returns the lab link interfaces of a node from its pod's clabwire listing. A pod is
// listed once, and again when its interfaces change (a pod gets its link interfaces as clabwire
// wires them).
func (p *interfacePoller) nodeLinks(
	ctx context.Context,
	target interfaceSampleTarget,
	names string,
) ([]clabwireInterface, error) {
	key := target.pod.Namespace + "/" + target.pod.Name

	p.listingsMu.Lock()
	listing := p.listings[key]
	p.listingsMu.Unlock()

	if listing == nil || listing.names != names {
		entries, err := p.r.listPodInterfaces(ctx, target.pod.Namespace, target.pod.Name)
		if err != nil {
			return nil, err
		}

		listing = &podInterfaceListing{
			names:  names,
			byNode: map[string][]clabwireInterface{},
		}
		for _, entry := range entries {
			listing.byNode[entry.Node] = append(listing.byNode[entry.Node], entry)
		}

		p.listingsMu.Lock()
		p.listings[key] = listing
		p.listingsMu.Unlock()
	}

	return listing.byNode[target.node.Name], nil
}

// commandNotExecutable reports an exec that failed because the command does not exist in the
// container.
func commandNotExecutable(rc int, err error) bool {
	if rc == exitCommandNotExecutable || rc == exitCommandNotFound {
		return true
	}

	return err != nil && strings.Contains(err.Error(), "executable file not found")
}

// reportedInterfaces are the interfaces reported for a node, by name, with the alias the
// topology gave them: its lab link interfaces, the management interface and loopback.
func reportedInterfaces(links []clabwireInterface) map[string]string {
	reported := map[string]string{
		loopbackInterface:   "",
		managementInterface: "",
	}
	for _, link := range links {
		reported[link.Interface] = link.Alias
	}

	return reported
}

// interfaceEventData describes an interface the way the local runtimes' netlink events do: the
// alias is the topology's name for the interface (an alias clabernetes set for its own use is
// not reported), the operational state uses netlink's names, lab link and management
// interfaces are veth pairs, loopback a device, and loopback has no hardware address.
func interfaceEventData(iface c9sIfaceState, alias string) clablabruntime.InterfaceEventData {
	if alias == "" && !strings.HasPrefix(iface.Alias, clabernetesAliasPrefix) {
		alias = iface.Alias
	}

	mac := iface.MAC
	if mac == zeroMAC {
		mac = ""
	}

	linkType := interfaceTypeVeth
	if iface.Name == loopbackInterface {
		linkType = interfaceTypeDevice
	}

	return clablabruntime.InterfaceEventData{
		Name:      iface.Name,
		Alias:     alias,
		Index:     iface.Index,
		MTU:       iface.MTU,
		MAC:       mac,
		OperState: netlinkOperState(iface.OperState),
		Type:      linkType,
	}
}

// netlinkOperState names an operational state from sysfs (RFC 2863, as in
// /sys/class/net/<if>/operstate) the way netlink, and so the local runtimes' events, name it.
func netlinkOperState(operState string) string {
	switch operState {
	case "notpresent":
		return "not-present"
	case "lowerlayerdown":
		return "lower-layer-down"
	case "":
		return "unknown"
	default:
		return operState
	}
}

func (p *interfacePoller) processSample(ctx context.Context, sample interfaceSample) {
	state := sample.target.state
	node := sample.target.node
	key := c9sNodeKey(state.Namespace, state.Name, node.Name)

	tracked, known := p.nodes[key]
	if !known {
		tracked = &trackedNode{ifaces: map[string]clablabruntime.InterfaceEventData{}}
		p.nodes[key] = tracked
	}
	tracked.lab = state
	tracked.node = node

	reported := reportedInterfaces(sample.links)

	if sample.hasStates {
		p.processStates(ctx, tracked, reported, sample)
	}

	if !p.opts.includeStats {
		return
	}
	for _, stat := range sample.stats {
		alias, ok := reported[stat.Name]
		if !ok {
			continue
		}

		statsKey := c9sIfaceStatsKey(state.Namespace, state.Name, node.Name, stat.Name)
		current := c9sIfaceStatsSample{Stats: stat, Timestamp: sample.timestamp}
		if previous, ok := p.statsSamples[statsKey]; ok {
			data, ok := tracked.ifaces[stat.Name]
			if !ok {
				data = interfaceEventData(c9sIfaceState{Name: stat.Name}, alias)
				data.OperState = ""
			}
			data.Stats = c9sIfaceStatsData(previous, current)
			p.emit(ctx, tracked, interfaceActionStats, data, current.Timestamp)
		}

		p.statsSamples[statsKey] = current
	}
}

// processStates reports the interfaces that appeared (snapshot in the first round with
// --initial-state, create later), changed (update) or disappeared (delete) since the last
// sample, like the netlink events of the local runtimes.
func (p *interfacePoller) processStates(
	ctx context.Context,
	tracked *trackedNode,
	reported map[string]string,
	sample interfaceSample,
) {
	present := map[string]bool{}
	for _, iface := range sample.ifaces {
		alias, ok := reported[iface.Name]
		if !ok {
			continue
		}

		data := interfaceEventData(iface, alias)
		present[iface.Name] = true
		previous, seen := tracked.ifaces[iface.Name]
		tracked.ifaces[iface.Name] = data

		switch {
		case seen && previous == data:
		case !seen && p.firstRound:
			// Interfaces that exist when the stream starts are only reported with
			// --initial-state; later changes are always reported.
			if p.opts.includeInitialState {
				p.emit(ctx, tracked, interfaceActionSnapshot, data, sample.timestamp)
			}
		case !seen:
			p.emit(ctx, tracked, interfaceActionCreate, data, sample.timestamp)
		default:
			p.emit(ctx, tracked, interfaceActionUpdate, data, sample.timestamp)
		}
	}

	for _, name := range sortedInterfaceNames(tracked.ifaces) {
		if present[name] {
			continue
		}

		p.emit(ctx, tracked, interfaceActionDelete, tracked.ifaces[name], sample.timestamp)
		p.forgetStats(tracked, name)
		delete(tracked.ifaces, name)
	}
}

func sortedInterfaceNames(ifaces map[string]clablabruntime.InterfaceEventData) []string {
	names := make([]string, 0, len(ifaces))
	for name := range ifaces {
		names = append(names, name)
	}
	sort.Strings(names)

	return names
}

func (p *interfacePoller) forgetStats(tracked *trackedNode, ifName string) {
	delete(p.statsSamples,
		c9sIfaceStatsKey(tracked.lab.Namespace, tracked.lab.Name, tracked.node.Name, ifName))
}

func (p *interfacePoller) emit(
	ctx context.Context,
	tracked *trackedNode,
	action string,
	data clablabruntime.InterfaceEventData,
	timestamp time.Time,
) {
	p.r.sendEvent(ctx, p.sink, c9sInterfaceEvent(tracked, action, data, timestamp))
}

// c9sInterfaceEvent is an interface event of a node. The actor is the node, as for its container
// events. The interface itself is in Interface; the events command reports it with the
// attributes of the local runtimes' interface events.
func c9sInterfaceEvent(
	tracked *trackedNode,
	action string,
	data clablabruntime.InterfaceEventData,
	timestamp time.Time,
) clablabruntime.Event {
	key := c9sNodeKey(tracked.lab.Namespace, tracked.lab.Name, tracked.node.Name)

	attributes := map[string]string{
		"namespace": tracked.lab.Namespace,
		"lab":       tracked.lab.Name,
		"node":      tracked.node.Name,
		"origin":    clabernetesAppValue,
	}
	if tracked.node.Pod != "" {
		attributes["pod"] = tracked.node.Pod
	}

	node := tracked.node

	return clablabruntime.Event{
		Timestamp:   timestamp,
		Type:        clablabruntime.EventTypeInterface,
		Action:      action,
		ActorID:     key,
		ActorName:   fmt.Sprintf("%s-%s", tracked.lab.Name, tracked.node.Name),
		ActorFullID: key,
		Attributes:  attributes,
		Lab:         tracked.lab,
		Node:        &node,
		Interface:   &data,
	}
}

// c9sIfaceStatsData computes the counters and rates of a stats event from two samples.
func c9sIfaceStatsData(previous, current c9sIfaceStatsSample) *clablabruntime.InterfaceStats {
	interval := current.Timestamp.Sub(previous.Timestamp)
	if interval <= 0 {
		interval = time.Second
	}

	seconds := interval.Seconds()
	stat := current.Stats

	return &clablabruntime.InterfaceStats{
		RxBytes:   stat.RxBytes,
		TxBytes:   stat.TxBytes,
		RxPackets: stat.RxPackets,
		TxPackets: stat.TxPackets,
		RxBps:     float64(counterDelta(stat.RxBytes, previous.Stats.RxBytes)*8) / seconds,
		TxBps:     float64(counterDelta(stat.TxBytes, previous.Stats.TxBytes)*8) / seconds,
		RxPps:     float64(counterDelta(stat.RxPackets, previous.Stats.RxPackets)) / seconds,
		TxPps:     float64(counterDelta(stat.TxPackets, previous.Stats.TxPackets)) / seconds,
		Interval:  interval,
	}
}

// parseInterfaceSample splits the output of interfaceSampleScript into the /proc/net/dev
// counters and the sysfs interface states. hasStates is false for output without the sysfs
// section, such as a plain cat of /proc/net/dev.
func parseInterfaceSample(data []byte) ([]c9sIfaceStats, []c9sIfaceState, bool, error) {
	text := string(data)

	procPart, sysfsPart, hasStates := strings.Cut(text, interfaceSysfsMarker+"\n")
	if !hasStates {
		procPart, _, hasStates = strings.Cut(text, interfaceSysfsMarker)
	}

	stats, err := parseProcNetDev([]byte(procPart))
	if err != nil {
		return nil, nil, false, err
	}
	if !hasStates {
		return stats, nil, false, nil
	}

	return stats, parseSysfsInterfaces(sysfsPart), true, nil
}

func parseSysfsInterfaces(data string) []c9sIfaceState {
	lines := strings.Split(data, "\n")
	states := make([]c9sIfaceState, 0, len(lines))

	for _, line := range lines {
		fields := strings.SplitN(line, "\t", 7) //nolint:mnd
		if len(fields) < 5 || strings.TrimSpace(fields[0]) == "" {
			continue
		}

		state := c9sIfaceState{
			Name:      strings.TrimSpace(fields[0]),
			MAC:       strings.TrimSpace(fields[3]),
			OperState: strings.ToLower(strings.TrimSpace(fields[4])),
		}
		state.Index, _ = strconv.Atoi(strings.TrimSpace(fields[1]))
		state.MTU, _ = strconv.Atoi(strings.TrimSpace(fields[2]))
		if len(fields) > 5 {
			state.Flags, _ = strconv.ParseUint(
				strings.TrimPrefix(strings.TrimSpace(fields[5]), "0x"), 16, 64)
		}
		if len(fields) > 6 {
			state.Alias = strings.TrimSpace(fields[6])
		}
		if state.OperState == "" {
			state.OperState = "unknown"
		}

		states = append(states, state)
	}

	return states
}

func parseProcNetDev(data []byte) ([]c9sIfaceStats, error) {
	lines := strings.Split(string(data), "\n")
	stats := make([]c9sIfaceStats, 0, len(lines))

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || !strings.Contains(line, ":") {
			continue
		}

		parts := strings.SplitN(line, ":", 2)
		if len(parts) != 2 {
			continue
		}

		ifName := strings.TrimSpace(parts[0])
		fields := strings.Fields(parts[1])
		if len(fields) < 16 {
			return nil, fmt.Errorf("unexpected /proc/net/dev line for %q: %q", ifName, line)
		}

		rxBytes, err := strconv.ParseUint(fields[0], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse rx bytes for %q: %w", ifName, err)
		}
		rxPackets, err := strconv.ParseUint(fields[1], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse rx packets for %q: %w", ifName, err)
		}
		txBytes, err := strconv.ParseUint(fields[8], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse tx bytes for %q: %w", ifName, err)
		}
		txPackets, err := strconv.ParseUint(fields[9], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse tx packets for %q: %w", ifName, err)
		}

		stats = append(stats, c9sIfaceStats{
			Name:      ifName,
			RxBytes:   rxBytes,
			RxPackets: rxPackets,
			TxBytes:   txBytes,
			TxPackets: txPackets,
		})
	}

	return stats, nil
}

// c9sNodeKey is the actor ID of a node: <namespace>/<lab>/<node>, the same value inspect
// reports as container_id.
func c9sNodeKey(namespace, lab, node string) string {
	return namespace + "/" + lab + "/" + node
}

func c9sIfaceStatsKey(namespace, lab, node, ifName string) string {
	return c9sNodeKey(namespace, lab, node) + "/" + ifName
}

func counterDelta(current, previous uint64) uint64 {
	if current < previous {
		return 0
	}

	return current - previous
}

package events

import (
	"context"
	"errors"
	"fmt"
	"math"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/charmbracelet/log"
	gotc "github.com/florianl/go-tc"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clabcore "github.com/srl-labs/containerlab/core"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clablinks "github.com/srl-labs/containerlab/links"
	clabnetem "github.com/srl-labs/containerlab/netem"
	clabruntime "github.com/srl-labs/containerlab/runtime"
	clabutils "github.com/srl-labs/containerlab/utils"
