// Copyright 2020 Nokia
// Licensed under the BSD 3-Clause License.
// SPDX-License-Identifier: BSD-3-Clause

package clabernetes

import (
	"context"
	"fmt"

	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	k8sruntime "k8s.io/apimachinery/pkg/runtime"
)

// Manifests renders the resources a deploy would create for the topology, in the order the
// runtime applies them, without contacting the cluster. The bundle is the managed lab
// Namespace when containerlab would create one, the staged ConfigMaps every node file mounts
// from, and then either the Topology resource or, for a lab deployed without one, the
// NodeProfile, Link, and Node resources compiled client-side. Every object carries the labels
// the runtime relies on to discover the lab later, so a bundle applied by hand stays
// manageable with inspect, destroy, and the node lifecycle commands.
func (r *Runtime) Manifests(
	ctx context.Context,
	req clablabruntime.DeployRequest,
) ([]clablabruntime.Manifest, error) {
	if req.Name == "" {
		return nil, fmt.Errorf("topology name is required")
	}
	if len(req.TopologyDefinition) == 0 {
		return nil, fmt.Errorf("rendered containerlab topology is required")
	}

	namespace, err := r.namespaceForLab(req.Name, req.Namespace)
	if err != nil {
		return nil, err
	}
	prepared, err := prepareDesiredDeployment(ctx, req, namespace)
	if err != nil {
		return nil, err
	}

	// The manifests are applied by other means than this deploy, so they do not carry the path
	// of the topology file on this machine; such a lab reports where its definition lives.
	removeTopologySourceFile(prepared.topology)
	for _, group := range prepared.primitives.groups() {
		for _, obj := range group.objects {
			removeTopologySourceFile(obj)
		}
	}

	manifests := []clablabruntime.Manifest{}

	// A namespace override must already exist, matching the deploy contract; only the
	// canonical per-lab namespace is created by containerlab and therefore emitted.
	if req.Namespace == "" && r.labNamespaceOverride == "" {
		manifest, err := typedManifest(labNamespaceObject(req.Name, namespace))
		if err != nil {
			return nil, err
		}
		manifests = append(manifests, manifest)
	}

	for _, staged := range prepared.configMaps {
		manifest, err := typedManifest(stagedConfigMapObject(namespace, req.Name, staged, nil))
		if err != nil {
			return nil, err
		}
		manifests = append(manifests, manifest)
	}

	if !req.NoTopologyCR {
		return append(manifests, unstructuredManifest(prepared.topology)), nil
	}

	for _, group := range prepared.primitives.groups() {
		for _, obj := range group.objects {
			manifests = append(manifests, unstructuredManifest(obj))
		}
	}

	return manifests, nil
}

func typedManifest(obj k8sruntime.Object) (clablabruntime.Manifest, error) {
	object, err := k8sruntime.DefaultUnstructuredConverter.ToUnstructured(obj)
	if err != nil {
		return clablabruntime.Manifest{}, fmt.Errorf("failed to render manifest: %w", err)
	}

	return unstructuredManifest(&unstructured.Unstructured{Object: object}), nil
}

// unstructuredManifest copies the object and strips the server-populated fields that typed
// conversion materializes as empty values, so the emitted document is a clean input for apply.
func unstructuredManifest(obj *unstructured.Unstructured) clablabruntime.Manifest {
	object := obj.DeepCopy().Object

	unstructured.RemoveNestedField(object, "status")
	if timestamp, found, _ := unstructured.NestedFieldNoCopy(
		object, "metadata", "creationTimestamp",
	); found && timestamp == nil {
		unstructured.RemoveNestedField(object, "metadata", "creationTimestamp")
	}
	if spec, found, _ := unstructured.NestedMap(object, "spec"); found && len(spec) == 0 {
		unstructured.RemoveNestedField(object, "spec")
	}

	copied := &unstructured.Unstructured{Object: object}

	return clablabruntime.Manifest{
		APIVersion: copied.GetAPIVersion(),
		Kind:       copied.GetKind(),
		Namespace:  copied.GetNamespace(),
		Name:       copied.GetName(),
		Object:     object,
	}
}

package clabernetes

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"sync"

	"github.com/charmbracelet/log"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clabtypes "github.com/srl-labs/containerlab/types"
	corev1 "k8s.io/api/core/v1"
	"k8s.io/client-go/kubernetes/scheme"
	"k8s.io/client-go/tools/remotecommand"
	kubeexec "k8s.io/client-go/util/exec"
)

// streamPodExec runs a command in a pod container without a terminal and streams its stdout
// and stderr. A non-nil stdin is attached: when it ends, the process's stdin is closed (the
// websocket v5 close signal, or a half-closed SPDY stream). A nonzero exit returns a
// *labruntime.CommandExitError.
func (r *Runtime) streamPodExec(
	ctx context.Context,
	namespace, pod, container string,
	command []string,
	stdin io.Reader,
	stdout, stderr io.Writer,
) error {
	execURL := r.kubeClient.CoreV1().RESTClient().Post().
		Resource("pods").
		Name(pod).
		Namespace(namespace).
		SubResource("exec").
		VersionedParams(&corev1.PodExecOptions{
			Container: container,
			Command:   command,
			Stdin:     stdin != nil,
			Stdout:    stdout != nil,
			Stderr:    stderr != nil,
		}, scheme.ParameterCodec).URL()

	executor, err := r.newExecutor(execURL)
	if err != nil {
		return err
	}

	// client-go reports streams cut by a cancelled context through the context's logger; a
	// capture ends that way on purpose, so it goes to the debug log
	err = executor.StreamWithContext(withKubernetesClientDebugLogs(ctx),
		remotecommand.StreamOptions{
			Stdin:  stdin,
			Stdout: stdout,
			Stderr: stderr,
		})

	var exitErr kubeexec.ExitError
	if errors.As(err, &exitErr) {
		return &clablabruntime.CommandExitError{Code: exitErr.ExitStatus()}
	}
	if err != nil {
		return fmt.Errorf("failed to execute command in pod %s/%s container %s: %w",
			namespace, pod, container, err)
	}

	return nil
}

// InspectInterfaces lists the interfaces of the requested nodes, or of every running node, in
// the shape of `inspect interfaces`, with the interfaces the interface events report: the lab
// link interfaces and their aliases as clabwire lists them, the management interface and
// loopback. Per node (named <lab>-<node> like in inspect) it reports the MAC address, index,
// MTU and operational state read from sysfs in the device container. A node whose device
// container has no shell reports its link interfaces without these attributes.
func (r *Runtime) InspectInterfaces(
	ctx context.Context,
	req clablabruntime.NodeRequest,
) ([]*clabtypes.ContainerInterfaces, error) {
	r, err := r.connect(ctx, req.Identity)
	if err != nil {
		return nil, err
	}

	locations, err := r.LocateNode(ctx, clablabruntime.NodeRequest{
		Name: req.Name, Namespace: req.Namespace, Nodes: req.Nodes, Identity: req.Identity,
	})
	if err != nil {
		return nil, err
	}

	running := make([]clablabruntime.NodeLocation, 0, len(locations))
	for _, location := range locations {
		if location.Pod == "" {
			log.Warn("Skipping interface detection of a node that does not run",
				"node", location.NodeName)
			continue
		}
		running = append(running, location)
	}

	listed, err := r.listCaptureInterfaces(ctx, req.Name, running)
	if err != nil {
		return nil, err
	}
	states := r.sampleInterfaceStates(ctx, running)

	result := make([]*clabtypes.ContainerInterfaces, 0, len(running))
	for _, location := range running {
		container := &clabtypes.ContainerInterfaces{
			ContainerName: req.Name + "-" + location.NodeName,
			Interfaces:    []*clabtypes.ContainerInterfaceDetails{},
		}
		sampled, hasStates := states[location.NodeName]
		for name, alias := range reportedInterfaces(listed[location.NodeName]) {
			state, ok := sampled[name]
			if !ok {
				if hasStates || (name == managementInterface || name == loopbackInterface) {
					// not present in the node (yet), or not known without its states
					continue
				}
				state = c9sIfaceState{Name: name}
			}

			data := interfaceEventData(state, alias)
			details := &clabtypes.ContainerInterfaceDetails{
				InterfaceName:  data.Name,
				InterfaceAlias: data.Alias,
				InterfaceType:  data.Type,
				InterfaceMAC:   data.MAC,
				InterfaceIndex: data.Index,
				InterfaceMTU:   data.MTU,
			}
			if ok {
				details.InterfaceState = data.OperState
			}
			container.Interfaces = append(container.Interfaces, details)
		}
		sort.Slice(container.Interfaces, func(i, j int) bool {
			return container.Interfaces[i].InterfaceName < container.Interfaces[j].InterfaceName
		})
		result = append(result, container)
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].ContainerName < result[j].ContainerName
	})

	return result, nil
}

// sampleInterfaceStates reads the sysfs interface attributes of every node's device container,
// one exec per node, with the script the interface events use.
func (r *Runtime) sampleInterfaceStates(
	ctx context.Context,
	locations []clablabruntime.NodeLocation,
) map[string]map[string]c9sIfaceState {
	var mu sync.Mutex
	result := map[string]map[string]c9sIfaceState{}

	var wg sync.WaitGroup
	workers := make(chan struct{}, interfaceSampleWorkers)
	exec := r.execInPodContainer()
	for _, location := range locations {
		wg.Add(1)
		go func() {
			defer wg.Done()
			workers <- struct{}{}
			defer func() { <-workers }()

			var stdout, stderr bytes.Buffer
			err := exec(ctx, location.Namespace, location.Pod, location.Container,
				[]string{"sh", "-c", interfaceSampleScript}, nil, &stdout, &stderr)
			if err != nil {
				log.Debug("Cannot read the interface state of a c9s node",
					"node", location.NodeName, "error", err)
				return
			}
			_, ifaces, _, err := parseInterfaceSample(stdout.Bytes())
			if err != nil {
				log.Debug("Cannot parse the interface state of a c9s node",
					"node", location.NodeName, "error", err)
				return
			}

			byName := make(map[string]c9sIfaceState, len(ifaces))
			for _, iface := range ifaces {
				byName[iface.Name] = iface
			}
			mu.Lock()
			result[location.NodeName] = byName
			mu.Unlock()
		}()
	}
	wg.Wait()

	return result
}

