package clabernetes

import (
	"fmt"
	"sort"

	"github.com/charmbracelet/log"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	"gopkg.in/yaml.v2"
	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	"k8s.io/apimachinery/pkg/util/validation"
)

type topologyObjectOption func(map[string]any)

// annotationTopologyFile records the absolute path of the topology file a lab was deployed from,
// on the machine that deployed it. Inspect reports it as the lab's topology path and events as
// clab-topo-file, as the local runtimes do, so clients match the running lab to its file. A lab
// created by other means than a containerlab deploy has no annotation and reports where its
// definition lives in the cluster (k8s://<namespace>/topologies/<lab>).
const annotationTopologyFile = "containerlab.dev/topo-file"

// setTopologySourceFile records the topology file a deploy reads on the Topology. An empty path
// (a definition that came from no file) records nothing.
func setTopologySourceFile(topology *unstructured.Unstructured, path string) {
	if path == "" {
		return
	}

	annotations := topology.GetAnnotations()
	if annotations == nil {
		annotations = map[string]string{}
	}
	annotations[annotationTopologyFile] = path
	topology.SetAnnotations(annotations)
}

// removeTopologySourceFile drops the deploying machine's file path from an object.
func removeTopologySourceFile(obj *unstructured.Unstructured) {
	annotations := obj.GetAnnotations()
	if _, ok := annotations[annotationTopologyFile]; !ok {
		return
	}

	delete(annotations, annotationTopologyFile)
	if len(annotations) == 0 {
		annotations = nil
	}
	obj.SetAnnotations(annotations)
}

// labTopologyPath is the topology path a lab reports: the file it was deployed from when the
// deploy recorded one, otherwise the place given.
func labTopologyPath(annotations map[string]string, fallback string) string {
	if path := annotations[annotationTopologyFile]; path != "" {
		return path
	}

	return fallback
}

func topologyWithNaming(naming string) topologyObjectOption {
	return func(spec map[string]any) {
		if naming != "" {
			spec["naming"] = naming
		}
	}
}

// topologyWithImagePullSecret sets the image pull secret the kubelet uses when pulling device
// images. An empty name leaves imagePull unset entirely: the controller fails closed on a named
// Secret that does not exist, so a Topology must only reference one the deploy actually asked
// for.
func topologyWithImagePullSecret(secret string) topologyObjectOption {
	return func(spec map[string]any) {
		if secret == "" {
			return
		}
		spec["imagePull"] = map[string]any{
			"pullSecrets": []any{secret},
		}
	}
}

func topologyWithExposeType(exposeType string) topologyObjectOption {
	return func(spec map[string]any) {
		if exposeType == "" {
			return
		}
		spec["expose"] = map[string]any{
			"exposeType": exposeType,
		}
	}
}

// topologyWithPersistence backs each node's artifact volume with a persistent claim so saved
// device configuration survives Pod replacement, the same contract a local runtime provides
// through the lab directory. The claims are retained when their Node is deleted, so a plain
// destroy keeps the saved configuration like the local lab directory, and a redeploy boots from
// it; destroy --cleanup deletes them. Disabled leaves persistence unset entirely: ephemeral
// storage is the CRD default.
func topologyWithPersistence(enabled bool) topologyObjectOption {
	return func(spec map[string]any) {
		if !enabled {
			return
		}
		deployment, ok := spec["deployment"].(map[string]any)
		if !ok {
			deployment = map[string]any{}
			spec["deployment"] = deployment
		}
		deployment["persistence"] = map[string]any{
			"enabled": true,
			"reclaim": persistenceReclaimRetain,
		}
	}
}

func topologyObject(
	name,
	namespace,
	owner,
	definition string,
	opts ...topologyObjectOption,
) *unstructured.Unstructured {
	topologyLabels := map[string]any{
		"containerlab.dev/runtime": clablabruntime.ClabernetesRuntimeName,
	}
	topologyAnnotations := map[string]any{}
	if owner != "" {
		topologyAnnotations[clabconstants.Owner] = owner
		if len(validation.IsValidLabelValue(owner)) == 0 {
			topologyLabels[clabconstants.Owner] = owner
		}
	}

	metadata := map[string]any{
		"name":      name,
		"namespace": namespace,
		"labels":    topologyLabels,
	}
	if len(topologyAnnotations) != 0 {
		metadata["annotations"] = topologyAnnotations
	}

	spec := map[string]any{
		"definition": map[string]any{
			"containerlab": definition,
		},
		// The runtime's readiness contract requires c9s status probes. Persist the setting
		// explicitly: CRD defaulting cannot materialize it in an absent statusProbes object, and
		// the controller's typed writes would then pin the zero value (disabled) instead. This
		// mirrors configurePrimitiveReadiness on the client-side compile.
		"statusProbes": map[string]any{
			"enabled": true,
		},
	}
	for _, opt := range opts {
		opt(spec)
	}

	return &unstructured.Unstructured{
		Object: map[string]any{
			"apiVersion": c9sAPIVersion,
			"kind":       "Topology",
			"metadata":   metadata,
			"spec":       spec,
		},
	}
}

// stateFromTopology builds the lab-state skeleton from a Topology CR. The direct-runtime
// Topology status intentionally carries only aggregate readiness -- per-node detail is always
// filled in from the Node objects and workloads by enrichState.
func stateFromTopology(obj *unstructured.Unstructured, namespace string) *clablabruntime.LabState {
	if obj.GetNamespace() != "" {
		namespace = obj.GetNamespace()
	}

	ready, _, _ := unstructured.NestedBool(obj.Object, "status", "topologyReady")
	state, _, _ := unstructured.NestedString(obj.Object, "status", "topologyState")
	owner := obj.GetLabels()[clabconstants.Owner]
	if owner == "" {
		owner = obj.GetAnnotations()[clabconstants.Owner]
	}
	nodeSpecs := nodeSpecsFromTopology(obj)
	topologyPath := labTopologyPath(
		obj.GetAnnotations(),
		fmt.Sprintf("k8s://%s/topologies/%s", namespace, obj.GetName()),
	)

	nodeNames := make([]string, 0, len(nodeSpecs))
	for nodeName := range nodeSpecs {
		nodeNames = append(nodeNames, nodeName)
	}
	sort.Strings(nodeNames)

	nodes := make([]clablabruntime.NodeState, 0, len(nodeNames))
	for _, nodeName := range nodeNames {
		spec := nodeSpecs[nodeName]
		nodes = append(nodes, clablabruntime.NodeState{
			Name:  nodeName,
			Kind:  spec.Kind,
			Image: spec.Image,
		})
	}

	return &clablabruntime.LabState{
		Name:         obj.GetName(),
		Namespace:    namespace,
		Owner:        owner,
		TopologyPath: topologyPath,
		State:        state,
		Ready:        ready,
		Nodes:        nodes,
	}
}

type nodeSpec struct {
	Kind  string `yaml:"kind"`
	Image string `yaml:"image"`
}

type containerlabDefinition struct {
	Topology struct {
		Nodes map[string]nodeSpec `yaml:"nodes"`
	} `yaml:"topology"`
}

func nodeSpecsFromTopology(obj *unstructured.Unstructured) map[string]nodeSpec {
	specs := map[string]nodeSpec{}

	definition, _, _ := unstructured.NestedString(
		obj.Object,
		"spec",
		"definition",
		"containerlab",
	)
	mergeNodeSpecs(specs, definition)

	return specs
}

func mergeNodeSpecs(specs map[string]nodeSpec, definition string) {
	if definition == "" {
		return
	}

	var parsed containerlabDefinition
	if err := yaml.Unmarshal([]byte(definition), &parsed); err != nil {
		log.Debug("failed to parse C9s topology definition", "error", err)
		return
	}

	for nodeName, spec := range parsed.Topology.Nodes {
		specs[nodeName] = spec
	}
}

