	"github.com/go-logr/logr/funcr"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	"k8s.io/apimachinery/pkg/runtime/schema"
	"k8s.io/client-go/dynamic"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	"k8s.io/klog/v2"
)

const (
	defaultNamespace = "default"
	pollInterval     = 2 * time.Second

	envKubeconfig = "CLAB_KUBECONFIG"
	envContext    = "CLAB_KUBE_CONTEXT"
	envNamespace  = "CLAB_KUBE_NAMESPACE"

	c9sAPIVersion         = "c9s.run/v1alpha1"
	labelRuntime          = "containerlab.dev/runtime"
	labelApp              = "c9s.run/app"
	labelTopologyOwner    = "c9s.run/topologyOwner"
	labelTopologyNode     = "c9s.run/topologyNode"
	labelOriginalNodeName = "c9s.run/originalNodeName"
	clabernetesAppValue   = "clabernetes"
	// persistenceReclaimRetain keeps a node's persistent claim when its Node is deleted.
	persistenceReclaimRetain = "Retain"
	// defaultContainerAnnotation names the primary device container of a c9s pod.
	defaultContainerAnnotation = "kubectl.kubernetes.io/default-container"
	// annotationDirectNodeUID names the UID of the Node a c9s pod runs.
	annotationDirectNodeUID = "c9s.run/direct-node-uid"
)

var topologyGVR = schema.GroupVersionResource{
	Group:    "c9s.run",
	Version:  "v1alpha1",
	Resource: "topologies",
}

var nodeGVR = schema.GroupVersionResource{
	Group:    "c9s.run",
	Version:  "v1alpha1",
	Resource: "nodes",
}

var linkGVR = schema.GroupVersionResource{
	Group:    "c9s.run",
	Version:  "v1alpha1",
	Resource: "links",
}

var nodeProfileGVR = schema.GroupVersionResource{
	Group:    "c9s.run",
	Version:  "v1alpha1",
	Resource: "nodeprofiles",
}

type Runtime struct {
	client     dynamic.Interface
	kubeClient kubernetes.Interface
	restConfig *rest.Config
	namespace  string
	// labNamespaceOverride is set by --namespace or CLAB_KUBE_NAMESPACE. When
	// empty, lab-scoped operations derive their namespace from the lab name.
	labNamespaceOverride string
	timeout              time.Duration
	// kindLinkApplyMode resolves the default link apply mode a node kind declares.
	// The plan uses it to predict the pod lifecycle impact of link changes.
	kindLinkApplyMode func(kind string) string
	// clients loads the Kubernetes clients on first use. Commands that only compile the
	// topology (validate, deploy --emit-crs) never call it, so they work without a
	// kubeconfig that loads. It is nil when the clients were injected (tests).
	clients *clientLoader
	// connected marks a runtime view whose client fields are populated.
	connected bool
	// identity is the configured identity of calls without one; in a connected view it is the
	// identity the clients impersonate.
	identity clablabruntime.Identity
	// pollInterval overrides how often waits poll the cluster (tests).
	pollInterval time.Duration
	// podExec overrides how commands run in pod containers (tests).
	podExec podExecFunc
	// captureSegment is the length of one chained packet capture; zero uses the clabwire
	// maximum of one hour.
	captureSegment time.Duration
	// captureReorderWindow is how long the merged capture stream holds packets back to write
	// them in timestamp order: zero uses the default, a negative value disables reordering.
	captureReorderWindow time.Duration
	// support checks once per runtime instance, before the first cluster call, that the
	// cluster runs a clabernetes release with the contract this runtime needs. Every view
	// shares it. It is nil when the clients were injected (tests).
	support *supportCheck
}

// kubeClients is the set of Kubernetes clients a runtime view operates with.
type kubeClients struct {
	dynamic    dynamic.Interface
	kube       kubernetes.Interface
	restConfig *rest.Config
}

// clientLoader loads the kubeconfig once and builds, and caches, the Kubernetes clients of
// every identity from it.
type clientLoader struct {
	loadConfig func() (*rest.Config, string, error)
	newClients func(*rest.Config) (*kubeClients, error)

	once      sync.Once
	base      *rest.Config
	namespace string
	err       error

	mu         sync.Mutex
	byIdentity map[string]*kubeClients
}

func newClientLoader() *clientLoader {
	return &clientLoader{
		loadConfig: kubeClientConfig,
		newClients: newKubeClients,
	}
}

func newKubeClients(restConfig *rest.Config) (*kubeClients, error) {
	client, err := dynamic.NewForConfig(restConfig)
	if err != nil {
		return nil, fmt.Errorf("failed to create Kubernetes dynamic client: %w", err)
	}

	kubeClient, err := kubernetes.NewForConfig(restConfig)
	if err != nil {
		return nil, fmt.Errorf("failed to create Kubernetes client: %w", err)
	}

	return &kubeClients{dynamic: client, kube: kubeClient, restConfig: restConfig}, nil
}

// load returns the clients of an identity. The impersonation is part of the rest config, so it
// applies to every transport built from it: REST calls, watches, log streams, and the SPDY and
// websocket upgrades of exec, attach and port-forward.
func (l *clientLoader) load(
	identity clablabruntime.Identity,
) (*kubeClients, string, error) {
	l.once.Do(func() {
		l.base, l.namespace, l.err = l.loadConfig()
		if l.namespace == "" {
			l.namespace = defaultNamespace
		}
	})
	if l.err != nil {
		return nil, "", l.err
	}

	key := identityKey(identity)

	l.mu.Lock()
	defer l.mu.Unlock()

	if clients, ok := l.byIdentity[key]; ok {
		return clients, l.namespace, nil
	}

	restConfig := rest.CopyConfig(l.base)
	if !identity.IsZero() {
		restConfig.Impersonate = rest.ImpersonationConfig{
			UserName: identity.User,
			Groups:   slices.Clone(identity.Groups),
		}
	}

	clients, err := l.newClients(restConfig)
	if err != nil {
		return nil, "", err
	}
	if l.byIdentity == nil {
		l.byIdentity = map[string]*kubeClients{}
	}
	l.byIdentity[key] = clients

	return clients, l.namespace, nil
}

func identityKey(identity clablabruntime.Identity) string {
	return identity.User + "\x00" + strings.Join(identity.Groups, "\x00")
}

// connect returns a view of the runtime with the Kubernetes clients of an identity populated,
// loading the kubeconfig on first use. A zero identity uses the runtime's configured identity.
// Every operation that reads or changes cluster state calls it first, so it also runs the
// clabernetes version check once per runtime instance, before the first cluster call.
func (r *Runtime) connect(
	ctx context.Context,
	identity clablabruntime.Identity,
) (*Runtime, error) {
	if identity.IsZero() {
		identity = r.identity
	}
	if r.connected && identity.Equal(r.identity) {
		return r, nil
	}
	if r.clients == nil {
		// clients were injected (tests); they act as the identity they were built with
		if err := r.support.ensure(ctx, r); err != nil {
			return nil, err
		}

		return r, nil
	}

	clients, namespace, err := r.clients.load(identity)
	if err != nil {
		return nil, err
	}

	view := *r
	view.client = clients.dynamic
	view.kubeClient = clients.kube
	view.restConfig = clients.restConfig
	if view.namespace == "" {
		view.namespace = namespace
	}
	view.identity = identity
	view.connected = true

	if err := r.support.ensure(ctx, &view); err != nil {
		return nil, err
	}

	return &view, nil
}

func withKubernetesClientDebugLogs(ctx context.Context) context.Context {
	verbosity := -1
	if log.GetLevel() <= log.DebugLevel {
		verbosity = 3
	}
	logger := funcr.New(func(prefix, args string) {
		log.Debug("Kubernetes client", "log", strings.TrimSpace(prefix+" "+args))
	}, funcr.Options{Verbosity: verbosity})

	return klog.NewContext(ctx, logger)
}

func init() {
	clablabruntime.Register(clablabruntime.ClabernetesRuntimeName, New)
}

// New returns the c9s lab runtime. It does not load the kubeconfig: the Kubernetes clients
// are created on the first operation that needs the cluster.
func New(cfg clablabruntime.Config) (clablabruntime.LabRuntime, error) {
	return &Runtime{
		labNamespaceOverride: configuredLabNamespace(cfg.Namespace),
		timeout:              cfg.Timeout,
		kindLinkApplyMode:    cfg.KindLinkApplyMode,
		identity:             cfg.Identity,
		clients:              newClientLoader(),
		support:              &supportCheck{},
		captureSegment:       captureSegmentFromEnv(),
		captureReorderWindow: captureReorderWindowFromEnv(),
	}, nil
}

package clabernetes

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"hash/fnv"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/charmbracelet/log"
	clabcapture "github.com/srl-labs/containerlab/capture"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	"golang.org/x/sync/errgroup"
)

// The clabwire packet capture contract (clabernetes 0.11 or newer).
const (
	clabwireContainer = "clabwire"
	clabwireManager   = "/clabernetes/manager"
	// captureAuditSchema is the schema of the JSON audit lines clabwire writes to stderr.
	captureAuditSchema = "c9s.direct-packet-capture-audit/v1alpha1"

	captureAuditStarted   = "Started"
	captureAuditSucceeded = "Succeeded"
	captureAuditFailed    = "Failed"
	captureAuditDenied    = "Denied"

	// maxCaptureSegment is the longest single clabwire capture; longer captures are chained.
	maxCaptureSegment = time.Hour
	// maxClabwirePackets is the packet limit of a single clabwire capture.
	maxClabwirePackets = 1_000_000
	// maxCaptureOverlap is how long two chained segments run side by side.
	maxCaptureOverlap = 10 * time.Second
	// maxCaptureCutWindow is the half-width of the window around the cut in which packets of
	// two segments are matched by content; it covers the difference between the timestamps
	// two clabwire processes give the same packet.
	maxCaptureCutWindow = 500 * time.Millisecond
	// minCaptureSegment is the shortest segment the chain requests.
	minCaptureSegment = 100 * time.Millisecond
	// captureEndGrace is how long a capture with a duration waits for its last clabwire
	// process to end after the duration passed.
	captureEndGrace = 30 * time.Second
	// captureStartRetries bounds the attempts to start a follow-up segment.
	captureStartRetries = 3
	// captureStdinCloseGrace is how long a segment's exec may take to end after its stdin was
	// closed before the stream is cut.
	captureStdinCloseGrace = 3 * time.Second
	// clabwireStopOnStdinClose makes clabwire end a capture when its stdin closes. A
	// Kubernetes exec does not stop its process when the stream ends, but it closes the
	// process's stdin, so every capture runs with stdin attached and this flag.
	clabwireStopOnStdinClose = "--stop-on-stdin-close"

	// envCaptureSegment overrides the segment length. It exists to exercise chaining in tests
	// without hour-long captures.
	envCaptureSegment = "CLAB_C9S_CAPTURE_SEGMENT"
	// defaultCaptureReorderWindow is how long the merged stream holds a packet back so packets
	// of other nodes stamped earlier but delivered later still go out before it.
	defaultCaptureReorderWindow = 250 * time.Millisecond
	// envCaptureReorderWindow overrides the reorder window; 0 writes packets as they arrive.
	// It is an internal knob, not a supported setting.
	envCaptureReorderWindow = "CLAB_C9S_CAPTURE_REORDER_WINDOW"
)

// podExecFunc runs a command in a pod container and streams its output. A nonzero exit returns
// a *labruntime.CommandExitError.
type podExecFunc func(
	ctx context.Context,
	namespace, pod, container string,
	command []string,
	stdin io.Reader,
	stdout, stderr io.Writer,
) error

// clabwireInterface is one entry of `packet-capture --list-interfaces`.
type clabwireInterface struct {
	Node          string `json:"node"`
	Interface     string `json:"interface"`
	Alias         string `json:"alias,omitempty"`
	PeerNode      string `json:"peerNode"`
	PeerInterface string `json:"peerInterface"`
}

// captureAudit is one clabwire audit line.
type captureAudit struct {
	SchemaVersion string    `json:"schemaVersion"`
	Time          time.Time `json:"time"`
	Status        string    `json:"status"`
	NodeName      string    `json:"nodeName"`
	Format        string    `json:"format"`
	Reason        string    `json:"reason"`
	Packets       int       `json:"packets"`
	Interfaces    []struct {
		Name    string `json:"name"`
		ID      string `json:"id"`
		Packets int    `json:"packets"`
	} `json:"interfaces"`
}

func (r *Runtime) execInPodContainer() podExecFunc {
	if r.podExec != nil {
		return r.podExec
	}

	return r.streamPodExec
}

// captureSegmentLength is the length of one clabwire capture before the next takes over.
func (r *Runtime) captureSegmentLength() time.Duration {
	if r.captureSegment > 0 && r.captureSegment <= maxCaptureSegment {
		return r.captureSegment
	}

	return maxCaptureSegment
}

// captureReorderWindowLength is the reorder window of the merged stream; zero disables
// reordering.
func (r *Runtime) captureReorderWindowLength() time.Duration {
	switch {
	case r.captureReorderWindow < 0:
		return 0
	case r.captureReorderWindow > 0:
		return r.captureReorderWindow
	}

	return defaultCaptureReorderWindow
}

// captureReorderWindowFromEnv reads the reorder window knob: unset or invalid keeps the
// default (0), "0" disables reordering (-1).
func captureReorderWindowFromEnv() time.Duration {
	value, err := time.ParseDuration(os.Getenv(envCaptureReorderWindow))
	switch {
	case err != nil || value < 0:
		return 0
	case value == 0:
		return -1
	}

	return value
}

func captureSegmentFromEnv() time.Duration {
	value, err := time.ParseDuration(os.Getenv(envCaptureSegment))
	if err != nil || value <= 0 {
		return 0
	}

	return value
}

// CaptureInterfaces lists the capturable lab link interfaces of the requested nodes, or of every
// node, as clabwire reports them, with their peers. Node names are reported as the topology
// spells them.
func (r *Runtime) CaptureInterfaces(
	ctx context.Context,
	req clablabruntime.NodeRequest,
) ([]clablabruntime.CaptureInterface, error) {
	r, err := r.connect(ctx, req.Identity)
	if err != nil {
		return nil, err
	}

	locations, err := r.LocateNode(ctx, clablabruntime.NodeRequest{
		Name: req.Name, Namespace: req.Namespace, Nodes: req.Nodes, Identity: req.Identity,
	})
	if err != nil {
		return nil, err
	}
	if len(req.Nodes) == 0 {
		// a lab-wide listing skips nodes that do not run
		running := locations[:0]
		for _, location := range locations {
			if location.Pod != "" {
				running = append(running, location)
			}
		}
		locations = running
	}

	listed, err := r.listCaptureInterfaces(ctx, req.Name, locations)
	if err != nil {
		return nil, err
	}
	names, err := r.nodeDisplayNames(ctx, req.Name, locations)
	if err != nil {
		return nil, err
	}

	result := make([]clablabruntime.CaptureInterface, 0)
	for _, location := range locations {
		for _, entry := range listed[location.NodeName] {
			result = append(result, clablabruntime.CaptureInterface{
				Node:          names.display(entry.Node),
				Interface:     entry.Interface,
				Alias:         entry.Alias,
				PeerNode:      names.display(entry.PeerNode),
				PeerInterface: entry.PeerInterface,
			})
		}
	}
	sort.SliceStable(result, func(i, j int) bool {
		if result[i].Node != result[j].Node {
			return result[i].Node < result[j].Node
		}

		return result[i].Interface < result[j].Interface
	})

	return result, nil
}

// listCaptureInterfaces runs one --list-interfaces per pod and returns the entries per Node.
func (r *Runtime) listCaptureInterfaces(
	ctx context.Context,
	lab string,
	locations []clablabruntime.NodeLocation,
) (map[string][]clabwireInterface, error) {
	pods := map[string]clablabruntime.NodeLocation{}
	wanted := map[string]bool{}
	for _, location := range locations {
		if location.Pod == "" {
			return nil, fmt.Errorf("c9s node %s/%s/%s has no pod; is it running?",
				location.Namespace, lab, location.NodeName)
		}
		pods[location.Namespace+"/"+location.Pod] = location
		wanted[location.NodeName] = true
	}

	var mu sync.Mutex
	result := map[string][]clabwireInterface{}
	group, groupCtx := errgroup.WithContext(ctx)
	group.SetLimit(interfaceSampleWorkers)
	for _, location := range pods {
		group.Go(func() error {
			entries, err := r.listPodInterfaces(groupCtx, location.Namespace, location.Pod)
			if err != nil {
				return err
			}

			mu.Lock()
			defer mu.Unlock()
			for _, entry := range entries {
				if wanted[entry.Node] {
					result[entry.Node] = append(result[entry.Node], entry)
				}
			}

			return nil
		})
	}
	if err := group.Wait(); err != nil {
		return nil, err
	}

	return result, nil
}

// listPodInterfaces runs clabwire's --list-interfaces in a pod: the lab link interfaces of the
// pod's nodes, with their aliases and peers.
func (r *Runtime) listPodInterfaces(
	ctx context.Context,
	namespace, pod string,
) ([]clabwireInterface, error) {
	var stdout, stderr bytes.Buffer
	err := r.execInPodContainer()(ctx, namespace, pod, clabwireContainer,
		[]string{clabwireManager, "node-runtime", "packet-capture", "--list-interfaces"},
		nil, &stdout, &stderr)
	if err != nil {
		return nil, fmt.Errorf("failed to list the capturable interfaces of pod %s/%s: %w%s",
			namespace, pod, err, stderrSuffix(stderr.Bytes()))
	}

	var entries []clabwireInterface
	if err := json.Unmarshal(stdout.Bytes(), &entries); err != nil {
		return nil, fmt.Errorf("failed to parse the capturable interfaces of pod %s/%s: %w",
			namespace, pod, err)
	}

	return entries, nil
}

func stderrSuffix(stderr []byte) string {
	text := strings.TrimSpace(string(stderr))
	if text == "" {
		return ""
	}

	return ": " + text
}

// nodeNames maps the node names the cluster carries to the names the topology file uses.
type nodeNames map[string]string

func (n nodeNames) display(name string) string {
	if original := n[name]; original != "" {
		return original
	}

	return name
}

// nodeDisplayNames reads the original node names from the c9s.run/originalNodeName label of the
// lab's Nodes.
func (r *Runtime) nodeDisplayNames(
	ctx context.Context,
	lab string,
	locations []clablabruntime.NodeLocation,
) (nodeNames, error) {
	names := nodeNames{}
	if len(locations) == 0 {
		return names, nil
	}

	nodes, err := r.nodesForTopology(ctx, lab, locations[0].Namespace)
	if err != nil {
		return nil, err
	}
	for idx := range nodes.Items {
		if original := nodes.Items[idx].GetLabels()[labelOriginalNodeName]; original != "" {
			names[nodes.Items[idx].GetName()] = original
		}
	}

	return names, nil
}

// captureGroup is the part of a capture one clabwire process serves: the requested interfaces of
// one node, in one pod.
type captureGroup struct {
	location clablabruntime.NodeLocation
	display  string
	// interfaces are the planned interface names, in the order the merged stream lists them.
	interfaces []string
	// ids are the merged interface IDs of interfaces.
	ids []uint32
}

// resolvedCapture is a validated capture request.
type resolvedCapture struct {
	groups []*captureGroup
	// names are the merged interface names (<node>:<interface>), indexed by merged ID.
	names []string
}

// resolveCaptureTargets locates every target node, checks every interface against the
// interfaces clabwire allows, and groups the targets per node.
func (r *Runtime) resolveCaptureTargets(
	ctx context.Context,
	req clablabruntime.CaptureRequest,
) (*resolvedCapture, error) {
	nodeOrder := make([]string, 0, len(req.Targets))
	seenNodes := map[string]bool{}
	for _, target := range req.Targets {
		if !seenNodes[target.Node] {
			seenNodes[target.Node] = true
			nodeOrder = append(nodeOrder, target.Node)
		}
	}

	locations, err := r.LocateNode(ctx, clablabruntime.NodeRequest{
		Name: req.Name, Namespace: req.Namespace, Nodes: nodeOrder, Identity: req.Identity,
	})
	if err != nil {
		return nil, err
	}
	byRequest := make(map[string]clablabruntime.NodeLocation, len(nodeOrder))
	for idx, name := range nodeOrder {
		byRequest[name] = locations[idx]
	}

	listed, err := r.listCaptureInterfaces(ctx, req.Name, locations)
	if err != nil {
		return nil, err
	}
	names, err := r.nodeDisplayNames(ctx, req.Name, locations)
	if err != nil {
		return nil, err
	}

	resolved := &resolvedCapture{}
	groups := map[string]*captureGroup{}
	seen := map[string]bool{}
	for _, target := range req.Targets {
		location := byRequest[target.Node]
		entry, ok := findCaptureInterface(listed[location.NodeName], target.Interface)
		if !ok {
			return nil, fmt.Errorf("interface %q of node %q is not a capturable link "+
				"interface; capturable: %s", target.Interface, target.Node,
				describeCaptureInterfaces(listed[location.NodeName]))
		}

		key := location.NodeName + "\x00" + entry.Interface
		if seen[key] {
			return nil, fmt.Errorf("interface %q of node %q is requested more than once",
				entry.Interface, target.Node)
		}
		seen[key] = true

		group := groups[location.NodeName]
		if group == nil {
			group = &captureGroup{
				location: location,
				display:  names.display(location.NodeName),
			}
			groups[location.NodeName] = group
			resolved.groups = append(resolved.groups, group)
		}

		id := uint32(len(resolved.names)) //nolint:gosec // bounded by the targets
		group.interfaces = append(group.interfaces, entry.Interface)
		group.ids = append(group.ids, id)
		resolved.names = append(resolved.names, group.display+":"+entry.Interface)
	}

	return resolved, nil
}

// findCaptureInterface matches a requested interface by its planned name or its alias.
func findCaptureInterface(entries []clabwireInterface, name string) (clabwireInterface, bool) {
	for _, entry := range entries {
		if entry.Interface == name {
			return entry, true
		}
	}
	for _, entry := range entries {
		if entry.Alias != "" && entry.Alias == name {
			return entry, true
		}
	}

	return clabwireInterface{}, false
}

func describeCaptureInterfaces(entries []clabwireInterface) string {
	if len(entries) == 0 {
		return "none"
	}

	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		name := entry.Interface
		if entry.Alias != "" {
			name += " (" + entry.Alias + ")"
		}
		names = append(names, name)
	}

	return strings.Join(names, ", ")
}

// Capture streams pcapng from lab link interfaces to w: one section, one Interface Description
// Block per target in request order named <node>:<interface>, then the packets of every target.
//
// Each node's interfaces are captured by one clabwire process in the node's pod. clabwire limits
// a capture to one hour, so a longer capture (or one without Duration) chains captures: the next
// one starts before the current one ends, and the stream switches at a cut in the overlap. See
// captureChain for how packets of the overlap are kept once.
//
// Packets go out in timestamp order across nodes, through a reorder buffer (captureReorder).
//
// Every clabwire process runs with stdin attached and --stop-on-stdin-close: a Kubernetes exec
// does not stop its process when the stream closes, so containerlab closes stdin whenever a
// segment ends (the capture ends, fails, its output fails, or a newer segment took over) and
// clabwire ends the capture itself.
//
// Capture returns when Duration has passed, PacketLimit packets were written, or ctx ends; an
// ended ctx is not an error. Every block reaches w in one write, so the stream is a valid capture
// whenever it stops. A clabwire Denied or Failed audit record is returned as an error.
func (r *Runtime) Capture(
	ctx context.Context,
	req clablabruntime.CaptureRequest,
	w io.Writer,
) error {
	if err := clabcapture.ValidateRequest(&req); err != nil {
		return err
	}

	r, err := r.connect(ctx, req.Identity)
	if err != nil {
		return err
	}

	resolved, err := r.resolveCaptureTargets(ctx, req)
	if err != nil {
		return err
	}

	captureCtx, stop := context.WithCancel(ctx)
	defer stop()

	out, err := clabcapture.NewOutput(w, resolved.names, req.SnapLength, req.PacketLimit,
		r.captureReorderWindowLength(), stop)
	if err != nil {
		return err
	}

	run := &captureRun{
		r:       r,
		req:     req,
		out:     out,
		segment: r.captureSegmentLength(),
	}
	if req.Duration > 0 {
		run.deadline = time.Now().Add(req.Duration)
	}
	run.overlap = min(maxCaptureOverlap, run.segment/3)
	run.window = min(maxCaptureCutWindow, run.overlap/4)

	if req.Duration > 0 {
		// a clabwire process that does not end on its own does not hold the capture open
		var cancelTimeout context.CancelFunc
		captureCtx, cancelTimeout = context.WithTimeout(captureCtx,
			req.Duration+run.overlap+captureEndGrace)
		defer cancelTimeout()
	}

	group, groupCtx := errgroup.WithContext(captureCtx)
	for _, captureGroup := range resolved.groups {
		chain := &captureChain{capture: run, group: captureGroup}
		group.Go(func() error {
			return chain.run(groupCtx)
		})
	}

	err = group.Wait()
	if writeErr := out.Close(); writeErr != nil {
		return writeErr
	}
	if err != nil && !(errors.Is(err, context.Canceled) && captureCtx.Err() != nil) {
		return err
	}

	return nil
}

// captureRun is the state a capture's chains share.
type captureRun struct {
	r   *Runtime
	req clablabruntime.CaptureRequest
	// out is the merged stream; it writes the packets of every chain in timestamp order and
	// stops every chain once the packet limit is reached.
	out *clabcapture.Output

	segment  time.Duration
	overlap  time.Duration
	window   time.Duration
	deadline time.Time
}

// emit writes a packet under its merged interface ID. It reports false once the packet limit is
// reached and the capture stops.
func (run *captureRun) emit(id uint32, packet *clabcapture.Packet) (bool, error) {
	return run.out.Emit(id, packet)
}

func (run *captureRun) reportGap(gap clablabruntime.CaptureGap) {
	clabcapture.ReportGap(run.req.OnGap, gap)
}

// captureSegment is one clabwire capture process of a chain.
type captureSegment struct {
	index      int
	localStart time.Time
	duration   time.Duration
	cancel     context.CancelFunc
	// closeStdin closes the stdin of the segment's clabwire process, which ends it; it may be
	// called any number of times.
	closeStdin func()
	// stopTimer closes stdin once the segment is no longer needed after a switch-over.
	stopTimer *time.Timer
	// started and ended are the pod-clock times of the Started and Succeeded audit records.
	started time.Time
	ended   time.Time
	done    bool
}

func (s *captureSegment) plannedEnd() time.Time {
	return s.started.Add(s.duration)
}

// segmentEvent is something a segment reported: a packet, an audit record, or its end.
type segmentEvent struct {
	segment *captureSegment
	packet  *clabcapture.Packet
	audit   *captureAudit
	done    bool
	err     error
}

// captureChain runs the chained clabwire captures of one group.
//
// Chaining and the cut: segment k+1 starts `overlap` before segment k is due to end, so both
// capture the same packets for a while. clabwire stamps packets when it reads them, so two
// processes give the same packet timestamps a few microseconds apart, and timestamps alone
// cannot pair them. The chain therefore cuts in the middle of the overlap and matches packets by
// content close to the cut:
//
//  1. When segment k+1 reports Started (pod clock, from its audit record), the cut is
//     T = midpoint of [Started(k+1), Started(k) + duration(k)]: both segments run then.
//  2. Segment k keeps streaming live, but only packets stamped before T; it remembers the
//     content of what it wrote since segment k+1 started.
//  3. Segment k+1's packets are held back until segment k has ended. Then the ones stamped
//     before T-W are dropped (segment k had them), the ones stamped within W of T are dropped
//     when segment k wrote the same bytes on the same interface, and every other one is written.
//     From then on segment k+1 streams live.
//
// Once the pod clock passed T+W, segment k's stdin is closed so it ends without running to its
// planned end. While packets are held back, the chain holds the reorder buffer at T-W, so other
// nodes' later packets do not overtake them in the merged stream.
//
// W (500 ms, less for short test segments) covers the stamping difference. Identical frames on
// the same interface within W of the cut can be paired with each other, which can drop a true
// repeat; nothing else is lost or doubled. A follow-up segment that does not start in time leaves
// a gap, which is reported through CaptureRequest.OnGap (or logged), never silently ignored.
type captureChain struct {
	capture *captureRun
	group   *captureGroup

	events chan segmentEvent
	wg     sync.WaitGroup

	active *captureSegment
	next   *captureSegment
	// cut is the switch time between active and next, in nanoseconds; zero until known.
	cut int64
	// emitted remembers the content of the packets active wrote while next runs.
	emitted map[uint64]int
	// held are the packets of next until active ends.
	held     []*clabcapture.Packet
	segments int
	retries  int
	// final is set once no further segment is due.
	final bool
	// stopping is set once ctx ended: the segments are asked to end and what they still
	// deliver is written.
	stopping bool
}

// run runs the chain until its last segment ended. When ctx ends, it stops the segments and
// keeps writing the packets they read until then; a segment that does not end within
// captureStdinCloseGrace is cut.
func (c *captureChain) run(ctx context.Context) error {
	c.events = make(chan segmentEvent, 256)
	// the segments outlive ctx so they can deliver their last packets; segmentsCtx cuts them
	segmentsCtx, cancel := context.WithCancel(context.WithoutCancel(ctx))
	var abort *time.Timer
	defer func() {
		if abort != nil {
			abort.Stop()
		}
		cancel()
		c.drain()
		c.capture.out.Release(c)
	}()

	c.active = c.start(segmentsCtx, c.segmentDuration(time.Now()))
	timer := time.NewTimer(c.nextStartIn())
	defer timer.Stop()

	done := ctx.Done()
	for {
		select {
		case <-done:
			done = nil
			c.stop(timer)
			abort = time.AfterFunc(captureStdinCloseGrace, cancel)
		case <-segmentsCtx.Done():
			return nil
		case <-timer.C:
			if c.next == nil && !c.final {
				c.startNext(segmentsCtx)
			}
		case event := <-c.events:
			stop, err := c.handle(segmentsCtx, event, timer)
			if err != nil || stop {
				return err
			}
		}
	}
}

// stop ends the chain early, like a deadline would: no further segment starts and the running
// ones are asked to end. The chain then writes what they deliver until they ended.
func (c *captureChain) stop(timer *time.Timer) {
	c.stopping = true
	c.final = true
	timer.Stop()
	c.active.closeStdin()
	if c.next != nil {
		c.next.closeStdin()
	}
}

// drain waits for the segment goroutines after the chain ended.
func (c *captureChain) drain() {
	done := make(chan struct{})
	go func() {
		c.wg.Wait()
		close(done)
	}()
	for {
		select {
		case <-done:
			return
		case <-c.events:
		}
	}
}

// segmentDuration is the requested duration of a segment starting now.
func (c *captureChain) segmentDuration(now time.Time) time.Duration {
	duration := c.capture.segment
	if !c.capture.deadline.IsZero() {
		duration = min(duration, c.capture.deadline.Sub(now))
	}

	return max(duration, minCaptureSegment)
}

// nextStartIn is the time until the follow-up of the active segment is due. It marks the chain
// final when none is due.
func (c *captureChain) nextStartIn() time.Duration {
	if c.stopping {
		c.final = true
		return maxCaptureSegment
	}
	activeEnd := c.active.localStart.Add(c.active.duration)
	if !c.capture.deadline.IsZero() &&
		!activeEnd.Before(c.capture.deadline.Add(-c.capture.window)) {
		c.final = true
		return maxCaptureSegment
	}
	c.final = false

	return max(time.Until(activeEnd.Add(-c.capture.overlap)), 0)
}

func (c *captureChain) startNext(ctx context.Context) {
	c.next = c.start(ctx, c.segmentDuration(time.Now()))
	c.emitted = map[uint64]int{}
	c.held = nil
	c.cut = 0
}

func (c *captureChain) handle(
	ctx context.Context,
	event segmentEvent,
	timer *time.Timer,
) (bool, error) {
	segment := event.segment

	switch {
	case event.audit != nil:
		return false, c.handleAudit(segment, event.audit)
	case event.packet != nil:
		return c.handlePacket(segment, event.packet)
	case event.done:
		segment.done = true
		if segment.stopTimer != nil {
			segment.stopTimer.Stop()
		}
		if event.err != nil && !c.stopping {
			if segment == c.next && segment.started.IsZero() && c.retries < captureStartRetries {
				// the follow-up did not start; try again while the active one still runs
				c.retries++
				log.Warn("Capture follow-up segment failed to start, retrying",
					"node", c.group.display, "error", event.err)
				c.next = nil
				resetTimer(timer, time.Second)

				return false, nil
			}

			return true, fmt.Errorf("capture on c9s node %s/%s/%s failed: %w",
				c.group.location.Namespace, c.capture.req.Name, c.group.display, event.err)
		}
		if segment != c.active {
			return false, nil
		}

		return c.switchSegments(ctx, timer)
	}

	return false, nil
}

func (c *captureChain) handleAudit(segment *captureSegment, audit *captureAudit) error {
	switch audit.Status {
	case captureAuditStarted:
		segment.started = audit.Time
		log.Debug("Capture segment started", "node", c.group.display, "segment", segment.index,
			"interfaces", strings.Join(c.group.interfaces, ","), "duration", segment.duration)
		if segment == c.next && !c.active.started.IsZero() {
			c.setCut()
		}
		if segment == c.next {
			c.retries = 0
		}
	case captureAuditSucceeded:
		segment.ended = audit.Time
		log.Debug("Capture segment succeeded", "node", c.group.display,
			"segment", segment.index, "packets", audit.Packets)
	case captureAuditDenied, captureAuditFailed:
		return captureAuditError(c.group.display, audit)
	}

	return nil
}

// captureAuditError turns a Denied or Failed clabwire audit record into an error.
func captureAuditError(node string, audit *captureAudit) error {
	verb := "failed"
	if audit.Status == captureAuditDenied {
		verb = "was denied"
	}
	interfaces := make([]string, 0, len(audit.Interfaces))
	for _, intf := range audit.Interfaces {
		interfaces = append(interfaces, intf.Name)
	}

	return fmt.Errorf("capture of %s on node %s %s by clabwire: %s",
		strings.Join(interfaces, ","), node, verb, audit.Reason)
}

// setCut places the cut in the middle of the overlap of the active and the next segment, both
// measured on the pod clock.
func (c *captureChain) setCut() {
	overlapStart := c.next.started
	overlapEnd := c.active.plannedEnd()
	if overlapEnd.Sub(overlapStart) < 2*c.capture.window {
		// the overlap is too short to match packets around a cut: the switch is reported as a
		// gap once the active segment ended
		c.cut = 0
		return
	}
	c.cut = overlapStart.Add(overlapEnd.Sub(overlapStart) / 2).UnixNano()

	window := c.capture.window.Nanoseconds()
	// Packets the next segment holds back are stamped from T-W on: other chains' packets after
	// that wait in the reorder buffer until the switch, so the merged stream stays in order.
	c.capture.out.Hold(c, c.cut-window)

	// The active segment only matters for packets stamped before T. Once the pod clock passed
	// T+W, it is closed: packets it read until then are still delivered, and the ones it reads
	// later are stamped after T and dropped anyway. The next segment's Started record was
	// written on the pod clock no later than now, so the pod clock passes T+W no later than
	// (T - Started + W) from now.
	active := c.active
	active.stopTimer = time.AfterFunc(
		time.Duration(c.cut-c.next.started.UnixNano()+window), active.closeStdin)
}

func (c *captureChain) handlePacket(
	segment *captureSegment,
	packet *clabcapture.Packet,
) (bool, error) {
	switch segment {
	case c.active:
		if c.cut != 0 && packet.Timestamp >= c.cut {
			return false, nil
		}
		if c.next != nil {
			c.emitted[packetKey(packet)]++
		}

		return c.emit(packet)
	case c.next:
		c.held = append(c.held, packet)
	}

	return false, nil
}

func (c *captureChain) emit(packet *clabcapture.Packet) (bool, error) {
	if int(packet.InterfaceID) >= len(c.group.ids) {
		return true, fmt.Errorf("clabwire wrote a packet for interface %d of %d",
			packet.InterfaceID, len(c.group.ids))
	}
	more, err := c.capture.emit(c.group.ids[packet.InterfaceID], packet)

	return !more, err
}

// switchSegments makes the next segment the active one after the active one ended, writing the
// held packets of the next one that the active one did not write.
func (c *captureChain) switchSegments(ctx context.Context, timer *time.Timer) (bool, error) {
	// the held packets are in the reorder buffer once this returns
	defer c.capture.out.Release(c)

	ended := c.active
	if c.stopping && c.next != nil && c.next.started.IsZero() {
		// the chain is stopping: a follow-up that has not started takes nothing over
		c.next, c.held, c.emitted, c.cut = nil, nil, nil, 0
	}
	if c.final && c.next == nil {
		return true, nil
	}

	if c.next == nil || c.next.started.IsZero() || c.cut == 0 {
		from := ended.ended
		if from.IsZero() {
			from = ended.plannedEnd()
		}
		gap := clablabruntime.CaptureGap{
			Node: c.group.display, Interfaces: c.group.interfaces, From: from,
			Reason: "the follow-up capture did not overlap the previous one",
		}
		if c.next != nil && !c.next.started.IsZero() {
			gap.To = c.next.started
		}
		c.capture.reportGap(gap)
	}

	if c.next != nil && c.next.done && !c.stopping {
		// the follow-up already ended (it started too late to take over): keep what it
		// captured and continue with a fresh segment
		for _, packet := range c.held {
			if stop, err := c.emit(packet); stop || err != nil {
				return true, err
			}
		}
		c.next, c.held, c.emitted, c.cut = nil, nil, nil, 0
	}

	if c.next == nil {
		if !c.capture.deadline.IsZero() &&
			!time.Now().Before(c.capture.deadline.Add(-c.capture.window)) {
			return true, nil
		}
		c.active = c.start(ctx, c.segmentDuration(time.Now()))
		resetTimer(timer, c.nextStartIn())

		return false, nil
	}

	window := c.capture.window.Nanoseconds()
	for _, packet := range c.held {
		if c.cut != 0 {
			if packet.Timestamp < c.cut-window {
				continue
			}
			if packet.Timestamp < c.cut+window {
				key := packetKey(packet)
				if c.emitted[key] > 0 {
					c.emitted[key]--
					continue
				}
			}
		}
		if stop, err := c.emit(packet); stop || err != nil {
			return true, err
		}
	}

	c.active, c.next = c.next, nil
	c.held, c.emitted, c.cut = nil, nil, 0
	if c.active.done {
		// the chain is stopping and the follow-up ended before the active one
		return true, nil
	}
	resetTimer(timer, c.nextStartIn())

	return false, nil
}

func resetTimer(timer *time.Timer, d time.Duration) {
	if !timer.Stop() {
		select {
		case <-timer.C:
		default:
		}
	}
	timer.Reset(d)
}

// packetKey identifies a packet by its interface and content.
func packetKey(packet *clabcapture.Packet) uint64 {
	hash := fnv.New64a()
	var id [4]byte
	id[0] = byte(packet.InterfaceID)
	id[1] = byte(packet.InterfaceID >> 8)
	_, _ = hash.Write(id[:])
	_, _ = hash.Write(packet.Data)

	return hash.Sum64()
}

// start runs one clabwire capture and reports its packets, audit records and end as events.
func (c *captureChain) start(ctx context.Context, duration time.Duration) *captureSegment {
	segmentCtx, cancel := context.WithCancel(ctx)
	stdinReader, stdinWriter := io.Pipe()
	segment := &captureSegment{
		index: c.segments, localStart: time.Now(), duration: duration, cancel: cancel,
		closeStdin: func() { _ = stdinWriter.Close() },
	}
	c.segments++

	command := []string{
		clabwireManager, "node-runtime", "packet-capture",
		"--nodeName", c.group.location.NodeName,
		"--format", "pcapng",
		"--snapLength", strconv.Itoa(c.capture.req.SnapLength),
		"--duration", duration.String(),
		clabwireStopOnStdinClose,
	}
	for _, name := range c.group.interfaces {
		command = append(command, "--interface", name)
	}
	if c.capture.req.PacketLimit > 0 {
		remaining := int64(c.capture.req.PacketLimit) - c.capture.out.Written()
		command = append(command, "--packetLimit",
			strconv.FormatInt(min(max(remaining, 1), maxClabwirePackets), 10))
	}

	send := func(event segmentEvent) {
		event.segment = segment
		select {
		case c.events <- event:
		case <-segmentCtx.Done():
		}
	}

	stdoutReader, stdoutWriter := io.Pipe()
	stderr := &auditLineWriter{send: func(audit *captureAudit) { send(segmentEvent{audit: audit}) }}

	// The exec outlives the segment's context by up to captureStdinCloseGrace: when the segment
	// ends for any reason (the capture is cancelled or failed, the output failed, or a newer
	// segment took over), its stdin is closed first so clabwire ends on its own, and the stream
	// is cut only if it does not.
	execCtx, cancelExec := context.WithCancel(context.WithoutCancel(segmentCtx))
	execDone := make(chan struct{})

	c.wg.Add(3)
	readDone := make(chan error, 1)
	go func() {
		defer c.wg.Done()
		readDone <- c.readSegment(stdoutReader, func(packet *clabcapture.Packet) {
			send(segmentEvent{packet: packet})
		})
		_, _ = io.Copy(io.Discard, stdoutReader)
	}()
	go func() {
		defer c.wg.Done()
		select {
		case <-execDone:
			return
		case <-segmentCtx.Done():
		}
		segment.closeStdin()
		grace := time.NewTimer(captureStdinCloseGrace)
		defer grace.Stop()
		select {
		case <-execDone:
		case <-grace.C:
			log.Debug("Capture segment did not end after its stdin closed, cutting the stream",
				"node", c.group.display, "segment", segment.index)
			cancelExec()
		}
	}()
	go func() {
		defer c.wg.Done()
		defer cancel()
		defer cancelExec()

		err := c.capture.r.execInPodContainer()(execCtx, c.group.location.Namespace,
			c.group.location.Pod, clabwireContainer, command, stdinReader, stdoutWriter, stderr)
		close(execDone)
		// the process ended: release the stdin copy of the exec stream
		segment.closeStdin()
		_ = stdoutWriter.Close()
		readErr := <-readDone
		stderr.flush()
		if err == nil && readErr != nil {
			err = readErr
		}
		if err != nil && stderr.text() != "" {
			if unsupported := unsupportedClabwire(
				c.group.location,
				stderr.text(),
			); unsupported != nil {
				err = unsupported
			} else {
				err = fmt.Errorf("%w: %s", err, stderr.text())
			}
		}
		send(segmentEvent{done: true, err: err})
	}()

	return segment
}

// unsupportedClabwire recognizes a clabwire that rejects --stop-on-stdin-close, which every
// capture passes: its release predates the capture contract the runtime needs.
func unsupportedClabwire(location clablabruntime.NodeLocation, stderr string) error {
	if !strings.Contains(stderr, "flag provided but not defined") ||
		!strings.Contains(stderr, strings.TrimPrefix(clabwireStopOnStdinClose, "-")) {
		return nil
	}

	return &unsupportedClabernetesError{reason: fmt.Sprintf(
		"clabwire in pod %s/%s does not accept packet-capture %s",
		location.Namespace, location.Pod, clabwireStopOnStdinClose)}
}

// readSegment checks that a segment's interfaces are the requested ones and passes its packets
// on with the segment's interface index.
func (c *captureChain) readSegment(stdout io.Reader, packet func(*clabcapture.Packet)) error {
	reader := clabcapture.NewReader(stdout)
	interfaces := 0
	for {
		event, err := reader.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if errors.Is(err, io.ErrUnexpectedEOF) {
			// the process was stopped inside a block
			return nil
		}
		if err != nil {
			return fmt.Errorf("failed to read the clabwire capture: %w", err)
		}
		if event.Interface != nil {
			if interfaces >= len(c.group.interfaces) ||
				event.Interface.Name != c.group.interfaces[interfaces] {
				return fmt.Errorf("clabwire described interface %q, want %s in order",
					event.Interface.Name, strings.Join(c.group.interfaces, ", "))
			}
			interfaces++
			continue
		}
		if event.Packet != nil {
			packet(event.Packet)
		}
	}
}

// auditLineWriter parses clabwire's stderr: audit records go to send, other lines are kept for
// error messages.
type auditLineWriter struct {
	send func(*captureAudit)

	mu      sync.Mutex
	partial []byte
	other   []string
}

func (w *auditLineWriter) Write(data []byte) (int, error) {
	w.mu.Lock()
	w.partial = append(w.partial, data...)
	var lines [][]byte
	for {
		idx := bytes.IndexByte(w.partial, '\n')
		if idx < 0 {
			break
		}
		lines = append(lines, append([]byte(nil), w.partial[:idx]...))
		w.partial = w.partial[idx+1:]
	}
	w.mu.Unlock()

	for _, line := range lines {
		w.line(line)
	}

	return len(data), nil
}

func (w *auditLineWriter) flush() {
	w.mu.Lock()
	line := w.partial
	w.partial = nil
	w.mu.Unlock()
	if len(bytes.TrimSpace(line)) != 0 {
		w.line(line)
	}
}

func (w *auditLineWriter) line(line []byte) {
	line = bytes.TrimSpace(line)
	if len(line) == 0 {
		return
	}

	var audit captureAudit
	if err := json.Unmarshal(
		line,
		&audit,
	); err == nil &&
		audit.SchemaVersion == captureAuditSchema {
		w.send(&audit)
		return
	}

	w.mu.Lock()
	defer w.mu.Unlock()
	if len(w.other) < 20 {
		w.other = append(w.other, string(line))
	}
}

func (w *auditLineWriter) text() string {
	w.mu.Lock()
	defer w.mu.Unlock()

	return strings.Join(w.other, "; ")
}

package clabernetes

import (
	"context"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/charmbracelet/log"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

const (
	// interfaceSysfsMarker separates the /proc/net/dev counters from the sysfs interface
	// attributes in the output of interfaceSampleScript.
	interfaceSysfsMarker = "@@clab-sysfs"
	// interfaceSampleScript reads the interface counters and, per interface, the sysfs
	// attributes the interface state events carry, in one exec:
	// name, ifindex, mtu, address, operstate, flags and ifalias, tab separated.
	interfaceSampleScript = `cat /proc/net/dev; echo ` + interfaceSysfsMarker + `; ` +
		`for d in /sys/class/net/*; do [ -e "$d/operstate" ] || continue; ` +
		`printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "${d##*/}" "$(cat "$d/ifindex")" ` +
		`"$(cat "$d/mtu")" "$(cat "$d/address")" "$(cat "$d/operstate")" ` +
		`"$(cat "$d/flags")" "$(cat "$d/ifalias")"; done 2>/dev/null`

	// interfaceSampleWorkers bounds the concurrent execs of one sampling round.
	interfaceSampleWorkers = 16

	// managementInterface is a node's management interface in its pod, the interface the
	// clabernetes planner gives the management address by default. It has the name the
	// management interface has in a container of the local runtimes.
	managementInterface = "eth0"
	// loopbackInterface is reported like the local runtimes report it.
	loopbackInterface = "lo"
	// clabernetesAliasPrefix starts the interface aliases clabernetes marks its own interfaces
	// and the lab links it wires with. They are not the topology's names, so they are not
	// reported.
	clabernetesAliasPrefix = "c9s:"
	// zeroMAC is the hardware address sysfs reports for interfaces without one (loopback).
	zeroMAC = "00:00:00:00:00:00"

	// Interface event actions and link types, as the local runtimes report them.
	interfaceActionSnapshot = "snapshot"
	interfaceActionCreate   = "create"
	interfaceActionUpdate   = "update"
	interfaceActionDelete   = "delete"
	interfaceActionStats    = "stats"
	interfaceTypeVeth       = "veth"
	interfaceTypeDevice     = "device"

	// shell exit codes of a command that cannot be found or executed.
	exitCommandNotExecutable = 126
	exitCommandNotFound      = 127
)

type interfacePollOptions struct {
	interval            time.Duration
	includeStats        bool
	includeInitialState bool
}

type c9sIfaceStats struct {
	Name      string
	RxBytes   uint64
	RxPackets uint64
	TxBytes   uint64
	TxPackets uint64
}

type c9sIfaceStatsSample struct {
	Stats     c9sIfaceStats
	Timestamp time.Time
}

// c9sIfaceState is the sysfs view of one interface in a device container.
type c9sIfaceState struct {
	Name      string
	Index     int
	MTU       int
	MAC       string
	OperState string
	Flags     uint64
	Alias     string
}

// trackedNode remembers the interfaces last reported for a node, so their changes and their
// removal can be reported, also when the node stops running.
type trackedNode struct {
	lab    *clablabruntime.LabState
	node   clablabruntime.NodeState
	ifaces map[string]clablabruntime.InterfaceEventData
}

type interfaceSampleTarget struct {
	state *clablabruntime.LabState
	node  clablabruntime.NodeState
	pod   *corev1.Pod
}

type interfaceSample struct {
	target    interfaceSampleTarget
	stats     []c9sIfaceStats
	ifaces    []c9sIfaceState
	hasStates bool
	// links are the node's lab link interfaces as clabwire lists them.
	links     []clabwireInterface
	timestamp time.Time
	err       error
}

// podInterfaceListing is the clabwire interface listing of a pod, per node. It is listed again
// when the pod's interfaces change.
type podInterfaceListing struct {
	names  string
	byNode map[string][]clabwireInterface
}

// interfacePoller samples the interfaces of every running node in an event scope and turns the
// samples into interface events. It reports the interfaces a container of the local runtimes
// has for the same node: the node's lab link interfaces, with the names and aliases clabwire
// lists for them, the management interface and loopback. The pod's own interfaces (the pod
// network, clabernetes' interposition and link transport interfaces) are not reported.
type interfacePoller struct {
	r     *Runtime
	scope eventScope
	opts  interfacePollOptions
	sink  chan<- clablabruntime.Event

	statsSamples map[string]c9sIfaceStatsSample
	nodes        map[string]*trackedNode

	noShellMu sync.Mutex
	// noShell holds the pods whose device container has no shell; they are sampled with a
	// plain cat of /proc/net/dev and report statistics without interface state.
	noShell map[string]bool

	listingsMu sync.Mutex
	// listings holds the clabwire interface listing per pod (namespace/pod).
	listings map[string]*podInterfaceListing

	firstRound bool
}

func (r *Runtime) pollInterfaces(
	ctx context.Context,
	scope eventScope,
	opts interfacePollOptions,
	eventSink chan<- clablabruntime.Event,
) {
	if opts.interval <= 0 {
		opts.interval = time.Second
	}

	poller := newInterfacePoller(r, scope, opts, eventSink)
	poller.round(ctx)

	ticker := time.NewTicker(opts.interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			poller.round(ctx)
		}
	}
}

func newInterfacePoller(
	r *Runtime,
	scope eventScope,
	opts interfacePollOptions,
	eventSink chan<- clablabruntime.Event,
) *interfacePoller {
	return &interfacePoller{
		r:            r,
		scope:        scope,
		opts:         opts,
		sink:         eventSink,
		statsSamples: map[string]c9sIfaceStatsSample{},
		nodes:        map[string]*trackedNode{},
		noShell:      map[string]bool{},
		listings:     map[string]*podInterfaceListing{},
		firstRound:   true,
	}
}

func (p *interfacePoller) round(ctx context.Context) {
	defer func() { p.firstRound = false }()

	states, err := p.r.labStates(ctx, p.scope)
	if err != nil {
		log.Debug("failed to list C9s labs for interface events", "error", err)
		return
	}

	running := map[string]bool{}
	pods := map[string]bool{}
	var targets []interfaceSampleTarget
	for _, state := range states {
		for _, node := range state.Nodes {
			if node.ContainerState != clablabruntime.ContainerStateRunning || node.Pod == "" ||
				node.Container == "" {
				continue
			}

			running[c9sNodeKey(state.Namespace, state.Name, node.Name)] = true
			pods[state.Namespace+"/"+node.Pod] = true
			targets = append(targets, interfaceSampleTarget{
				state: state,
				node:  node,
				pod: &corev1.Pod{ObjectMeta: metav1.ObjectMeta{
					Name:      node.Pod,
					Namespace: state.Namespace,
				}},
			})
		}
	}

	for _, sample := range p.sampleAll(ctx, targets) {
		if ctx.Err() != nil {
			return
		}
		if sample.err != nil {
			log.Debug("failed to sample C9s interfaces",
				"namespace", sample.target.state.Namespace,
				"lab", sample.target.state.Name,
				"node", sample.target.node.Name,
				"error", sample.err,
			)

			continue
		}

		p.processSample(ctx, sample)
	}

	p.retireStoppedNodes(ctx, running)
	p.forgetListings(pods)
}

// retireStoppedNodes reports the interfaces of nodes that stopped running, or were removed, as
// deleted: they are gone with the node's pod.
func (p *interfacePoller) retireStoppedNodes(ctx context.Context, running map[string]bool) {
	for key, tracked := range p.nodes {
		if running[key] {
			continue
		}

		for _, name := range sortedInterfaceNames(tracked.ifaces) {
			p.emit(ctx, tracked, interfaceActionDelete, tracked.ifaces[name], time.Now())
			p.forgetStats(tracked, name)
		}
		delete(p.nodes, key)
	}
}

// forgetListings drops the interface listings of pods that are gone.
func (p *interfacePoller) forgetListings(pods map[string]bool) {
	p.listingsMu.Lock()
	defer p.listingsMu.Unlock()

	for key := range p.listings {
		if !pods[key] {
			delete(p.listings, key)
		}
	}
}

func (p *interfacePoller) sampleAll(
	ctx context.Context,
	targets []interfaceSampleTarget,
) []interfaceSample {
	samples := make([]interfaceSample, len(targets))

	var wg sync.WaitGroup
	sem := make(chan struct{}, interfaceSampleWorkers)
	for idx := range targets {
		wg.Add(1)
		sem <- struct{}{}
		go func(idx int) {
			defer wg.Done()
			defer func() { <-sem }()

			samples[idx] = p.sample(ctx, targets[idx])
		}(idx)
	}
	wg.Wait()

	return samples
}

func (p *interfacePoller) sample(
	ctx context.Context,
	target interfaceSampleTarget,
) interfaceSample {
	sample := interfaceSample{target: target}
	podName := target.pod.Name

	p.noShellMu.Lock()
	noShell := p.noShell[podName]
	p.noShellMu.Unlock()

	command := []string{"sh", "-c", interfaceSampleScript}
	if noShell {
		command = []string{"cat", "/proc/net/dev"}
	}

	stdout, stderr, rc, err := p.r.execInPod(ctx, target.pod, target.node.Container, command)
	if !noShell && commandNotExecutable(rc, err) {
		p.noShellMu.Lock()
		p.noShell[podName] = true
		p.noShellMu.Unlock()

		log.Debug("C9s device container has no shell; reporting interface statistics only",
			"namespace", target.state.Namespace,
			"lab", target.state.Name,
			"node", target.node.Name,
		)

		stdout, stderr, rc, err = p.r.execInPod(ctx, target.pod, target.node.Container,
			[]string{"cat", "/proc/net/dev"})
	}

	sample.timestamp = time.Now()
	switch {
	case err != nil:
		sample.err = err
	case rc != 0:
		sample.err = fmt.Errorf("exit code %d: %s", rc, strings.TrimSpace(string(stderr)))
	default:
		sample.stats, sample.ifaces, sample.hasStates, sample.err = parseInterfaceSample(stdout)
	}
	if sample.err != nil {
		return sample
	}

	sample.links, sample.err = p.nodeLinks(ctx, target, sampledInterfaceNames(sample))

	return sample
}

// sampledInterfaceNames lists the interface names a sample saw, sorted and comma-joined.
func sampledInterfaceNames(sample interfaceSample) string {
	names := make([]string, 0, len(sample.stats)+len(sample.ifaces))
	seen := map[string]bool{}
	for _, iface := range sample.ifaces {
		if !seen[iface.Name] {
			seen[iface.Name] = true
			names = append(names, iface.Name)
		}
	}
	for _, stat := range sample.stats {
		if !seen[stat.Name] {
			seen[stat.Name] = true
			names = append(names, stat.Name)
		}
	}
	sort.Strings(names)

	return strings.Join(names, ",")
}

// nodeLinks returns the lab link interfaces of a node from its pod's clabwire listing. A pod is
// listed once, and again when its interfaces change (a pod gets its link interfaces as clabwire
// wires them).
func (p *interfacePoller) nodeLinks(
	ctx context.Context,
	target interfaceSampleTarget,
	names string,
) ([]clabwireInterface, error) {
	key := target.pod.Namespace + "/" + target.pod.Name

	p.listingsMu.Lock()
	listing := p.listings[key]
	p.listingsMu.Unlock()

	if listing == nil || listing.names != names {
		entries, err := p.r.listPodInterfaces(ctx, target.pod.Namespace, target.pod.Name)
		if err != nil {
			return nil, err
		}

		listing = &podInterfaceListing{
			names:  names,
			byNode: map[string][]clabwireInterface{},
		}
		for _, entry := range entries {
			listing.byNode[entry.Node] = append(listing.byNode[entry.Node], entry)
		}

		p.listingsMu.Lock()
		p.listings[key] = listing
		p.listingsMu.Unlock()
	}

	return listing.byNode[target.node.Name], nil
}

// commandNotExecutable reports an exec that failed because the command does not exist in the
// container.
func commandNotExecutable(rc int, err error) bool {
	if rc == exitCommandNotExecutable || rc == exitCommandNotFound {
		return true
	}

	return err != nil && strings.Contains(err.Error(), "executable file not found")
}

// reportedInterfaces are the interfaces reported for a node, by name, with the alias the
// topology gave them: its lab link interfaces, the management interface and loopback.
func reportedInterfaces(links []clabwireInterface) map[string]string {
	reported := map[string]string{
		loopbackInterface:   "",
		managementInterface: "",
	}
	for _, link := range links {
		reported[link.Interface] = link.Alias
	}

	return reported
}

// interfaceEventData describes an interface the way the local runtimes' netlink events do: the
// alias is the topology's name for the interface (an alias clabernetes set for its own use is
// not reported), the operational state uses netlink's names, lab link and management
// interfaces are veth pairs, loopback a device, and loopback has no hardware address.
func interfaceEventData(iface c9sIfaceState, alias string) clablabruntime.InterfaceEventData {
	if alias == "" && !strings.HasPrefix(iface.Alias, clabernetesAliasPrefix) {
		alias = iface.Alias
	}

	mac := iface.MAC
	if mac == zeroMAC {
		mac = ""
	}

	linkType := interfaceTypeVeth
	if iface.Name == loopbackInterface {
		linkType = interfaceTypeDevice
	}

	return clablabruntime.InterfaceEventData{
		Name:      iface.Name,
		Alias:     alias,
		Index:     iface.Index,
		MTU:       iface.MTU,
		MAC:       mac,
		OperState: netlinkOperState(iface.OperState),
		Type:      linkType,
	}
}

// netlinkOperState names an operational state from sysfs (RFC 2863, as in
// /sys/class/net/<if>/operstate) the way netlink, and so the local runtimes' events, name it.
func netlinkOperState(operState string) string {
	switch operState {
	case "notpresent":
		return "not-present"
	case "lowerlayerdown":
		return "lower-layer-down"
	case "":
		return "unknown"
	default:
		return operState
	}
}

func (p *interfacePoller) processSample(ctx context.Context, sample interfaceSample) {
	state := sample.target.state
	node := sample.target.node
	key := c9sNodeKey(state.Namespace, state.Name, node.Name)

	tracked, known := p.nodes[key]
	if !known {
		tracked = &trackedNode{ifaces: map[string]clablabruntime.InterfaceEventData{}}
		p.nodes[key] = tracked
	}
	tracked.lab = state
	tracked.node = node

	reported := reportedInterfaces(sample.links)

	if sample.hasStates {
		p.processStates(ctx, tracked, reported, sample)
	}

	if !p.opts.includeStats {
		return
	}
	for _, stat := range sample.stats {
		alias, ok := reported[stat.Name]
		if !ok {
			continue
		}

		statsKey := c9sIfaceStatsKey(state.Namespace, state.Name, node.Name, stat.Name)
		current := c9sIfaceStatsSample{Stats: stat, Timestamp: sample.timestamp}
		if previous, ok := p.statsSamples[statsKey]; ok {
			data, ok := tracked.ifaces[stat.Name]
			if !ok {
				data = interfaceEventData(c9sIfaceState{Name: stat.Name}, alias)
				data.OperState = ""
			}
			data.Stats = c9sIfaceStatsData(previous, current)
			p.emit(ctx, tracked, interfaceActionStats, data, current.Timestamp)
		}

		p.statsSamples[statsKey] = current
	}
}

// processStates reports the interfaces that appeared (snapshot in the first round with
// --initial-state, create later), changed (update) or disappeared (delete) since the last
// sample, like the netlink events of the local runtimes.
func (p *interfacePoller) processStates(
	ctx context.Context,
	tracked *trackedNode,
	reported map[string]string,
	sample interfaceSample,
) {
	present := map[string]bool{}
	for _, iface := range sample.ifaces {
		alias, ok := reported[iface.Name]
		if !ok {
			continue
		}

		data := interfaceEventData(iface, alias)
		present[iface.Name] = true
		previous, seen := tracked.ifaces[iface.Name]
		tracked.ifaces[iface.Name] = data

		switch {
		case seen && previous == data:
		case !seen && p.firstRound:
			// Interfaces that exist when the stream starts are only reported with
			// --initial-state; later changes are always reported.
			if p.opts.includeInitialState {
				p.emit(ctx, tracked, interfaceActionSnapshot, data, sample.timestamp)
			}
		case !seen:
			p.emit(ctx, tracked, interfaceActionCreate, data, sample.timestamp)
		default:
			p.emit(ctx, tracked, interfaceActionUpdate, data, sample.timestamp)
		}
	}

	for _, name := range sortedInterfaceNames(tracked.ifaces) {
		if present[name] {
			continue
		}

		p.emit(ctx, tracked, interfaceActionDelete, tracked.ifaces[name], sample.timestamp)
		p.forgetStats(tracked, name)
		delete(tracked.ifaces, name)
	}
}

func sortedInterfaceNames(ifaces map[string]clablabruntime.InterfaceEventData) []string {
	names := make([]string, 0, len(ifaces))
	for name := range ifaces {
		names = append(names, name)
	}
	sort.Strings(names)

	return names
}

func (p *interfacePoller) forgetStats(tracked *trackedNode, ifName string) {
	delete(p.statsSamples,
		c9sIfaceStatsKey(tracked.lab.Namespace, tracked.lab.Name, tracked.node.Name, ifName))
}

func (p *interfacePoller) emit(
	ctx context.Context,
	tracked *trackedNode,
	action string,
	data clablabruntime.InterfaceEventData,
	timestamp time.Time,
) {
	p.r.sendEvent(ctx, p.sink, c9sInterfaceEvent(tracked, action, data, timestamp))
}

// c9sInterfaceEvent is an interface event of a node. The actor is the node, as for its container
// events. The interface itself is in Interface; the events command reports it with the
// attributes of the local runtimes' interface events.
func c9sInterfaceEvent(
	tracked *trackedNode,
	action string,
	data clablabruntime.InterfaceEventData,
	timestamp time.Time,
) clablabruntime.Event {
	key := c9sNodeKey(tracked.lab.Namespace, tracked.lab.Name, tracked.node.Name)

	attributes := map[string]string{
		"namespace": tracked.lab.Namespace,
		"lab":       tracked.lab.Name,
		"node":      tracked.node.Name,
		"origin":    clabernetesAppValue,
	}
	if tracked.node.Pod != "" {
		attributes["pod"] = tracked.node.Pod
	}

	node := tracked.node

	return clablabruntime.Event{
		Timestamp:   timestamp,
		Type:        clablabruntime.EventTypeInterface,
		Action:      action,
		ActorID:     key,
		ActorName:   fmt.Sprintf("%s-%s", tracked.lab.Name, tracked.node.Name),
		ActorFullID: key,
		Attributes:  attributes,
		Lab:         tracked.lab,
		Node:        &node,
		Interface:   &data,
	}
}

// c9sIfaceStatsData computes the counters and rates of a stats event from two samples.
func c9sIfaceStatsData(previous, current c9sIfaceStatsSample) *clablabruntime.InterfaceStats {
	interval := current.Timestamp.Sub(previous.Timestamp)
	if interval <= 0 {
		interval = time.Second
	}

	seconds := interval.Seconds()
	stat := current.Stats

	return &clablabruntime.InterfaceStats{
		RxBytes:   stat.RxBytes,
		TxBytes:   stat.TxBytes,
		RxPackets: stat.RxPackets,
		TxPackets: stat.TxPackets,
		RxBps:     float64(counterDelta(stat.RxBytes, previous.Stats.RxBytes)*8) / seconds,
		TxBps:     float64(counterDelta(stat.TxBytes, previous.Stats.TxBytes)*8) / seconds,
		RxPps:     float64(counterDelta(stat.RxPackets, previous.Stats.RxPackets)) / seconds,
		TxPps:     float64(counterDelta(stat.TxPackets, previous.Stats.TxPackets)) / seconds,
		Interval:  interval,
	}
}

// parseInterfaceSample splits the output of interfaceSampleScript into the /proc/net/dev
// counters and the sysfs interface states. hasStates is false for output without the sysfs
// section, such as a plain cat of /proc/net/dev.
func parseInterfaceSample(data []byte) ([]c9sIfaceStats, []c9sIfaceState, bool, error) {
	text := string(data)

	procPart, sysfsPart, hasStates := strings.Cut(text, interfaceSysfsMarker+"\n")
	if !hasStates {
		procPart, _, hasStates = strings.Cut(text, interfaceSysfsMarker)
	}

	stats, err := parseProcNetDev([]byte(procPart))
	if err != nil {
		return nil, nil, false, err
	}
	if !hasStates {
		return stats, nil, false, nil
	}

	return stats, parseSysfsInterfaces(sysfsPart), true, nil
}

func parseSysfsInterfaces(data string) []c9sIfaceState {
	lines := strings.Split(data, "\n")
	states := make([]c9sIfaceState, 0, len(lines))

	for _, line := range lines {
		fields := strings.SplitN(line, "\t", 7) //nolint:mnd
		if len(fields) < 5 || strings.TrimSpace(fields[0]) == "" {
			continue
		}

		state := c9sIfaceState{
			Name:      strings.TrimSpace(fields[0]),
			MAC:       strings.TrimSpace(fields[3]),
			OperState: strings.ToLower(strings.TrimSpace(fields[4])),
		}
		state.Index, _ = strconv.Atoi(strings.TrimSpace(fields[1]))
		state.MTU, _ = strconv.Atoi(strings.TrimSpace(fields[2]))
		if len(fields) > 5 {
			state.Flags, _ = strconv.ParseUint(
				strings.TrimPrefix(strings.TrimSpace(fields[5]), "0x"), 16, 64)
		}
		if len(fields) > 6 {
			state.Alias = strings.TrimSpace(fields[6])
		}
		if state.OperState == "" {
			state.OperState = "unknown"
		}

		states = append(states, state)
	}

	return states
}

func parseProcNetDev(data []byte) ([]c9sIfaceStats, error) {
	lines := strings.Split(string(data), "\n")
	stats := make([]c9sIfaceStats, 0, len(lines))

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || !strings.Contains(line, ":") {
			continue
		}

		parts := strings.SplitN(line, ":", 2)
		if len(parts) != 2 {
			continue
		}

		ifName := strings.TrimSpace(parts[0])
		fields := strings.Fields(parts[1])
		if len(fields) < 16 {
			return nil, fmt.Errorf("unexpected /proc/net/dev line for %q: %q", ifName, line)
		}

		rxBytes, err := strconv.ParseUint(fields[0], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse rx bytes for %q: %w", ifName, err)
		}
		rxPackets, err := strconv.ParseUint(fields[1], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse rx packets for %q: %w", ifName, err)
		}
		txBytes, err := strconv.ParseUint(fields[8], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse tx bytes for %q: %w", ifName, err)
		}
		txPackets, err := strconv.ParseUint(fields[9], 10, 64)
		if err != nil {
			return nil, fmt.Errorf("failed to parse tx packets for %q: %w", ifName, err)
		}

		stats = append(stats, c9sIfaceStats{
			Name:      ifName,
			RxBytes:   rxBytes,
			RxPackets: rxPackets,
			TxBytes:   txBytes,
			TxPackets: txPackets,
		})
	}

	return stats, nil
}

// c9sNodeKey is the actor ID of a node: <namespace>/<lab>/<node>, the same value inspect
// reports as container_id.
func c9sNodeKey(namespace, lab, node string) string {
	return namespace + "/" + lab + "/" + node
}

func c9sIfaceStatsKey(namespace, lab, node, ifName string) string {
	return c9sNodeKey(namespace, lab, node) + "/" + ifName
}

func counterDelta(current, previous uint64) uint64 {
	if current < previous {
		return 0
	}

	return current - previous
}

